programs.sol:
"""A partial lexical/context approximation, not a single semantic detector.

At document starts, use signed responses for articles, question words,
code declarations and separators, with coarse script/case/shape averages
otherwise. Keep that response while the initial token repeats unchanged.
Within documents, recognize a few Chinese website, reader-address,
computing and examination phrases; IT near non-ASCII letters is negative.
URL and escape separators also have small responses. Everything else is
zero. Most of the component's lexical variation remains unexplained.
"""
import re
import regex
import unicodedata

READS = ()


def start_value(s):
    word = s.strip()
    lower = word.lower()
    if word == '<|im_start|>':
        return 0.50
    if word == '<|endoftext|>':
        return 1.31
    if word and set(word) == {'·'}:
        return 2.01
    if s == r'\n':
        return 1.87
    if s == r'\t':
        return 1.17
    if s == '\t':
        return 0.82
    if s.isspace():
        return 0.20
    if word == ':' or s in ('.\n', ':\n'):
        return 0.65
    if word.isascii() and word.isdigit():
        return 0.19 if word == '0' else -0.28
    if lower in ('a', 'an', 'the'):
        if s.startswith(' ') and word.islower():
            return 0.55
        return 0.29 if word[0].isupper() else -0.15
    if lower in ('and', 'but'):
        return -0.65 if s.startswith(' ') else -0.95
    if lower in ('i', 'he', 'she', 'they'):
        return -0.47
    if lower in ('are', 'be'):
        return -0.50
    if lower in ('have', 'has', 'had'):
        return -0.28
    if word in ('How', 'What', 'Why', 'Does'):
        return 1.0
    if word in ('When', 'Is', 'Do'):
        return 0.62
    if lower in ('of', 'as', 'in', 'from'):
        return 0.35
    if lower in ('at', 'with', 'by'):
        return -0.40
    if lower == 'to':
        return -0.14
    # Language-specific declaration words, only at the document's start.
    if s in ('import', 'function', 'var', 'theorem'):
        return 1.05
    if s in ('package', 'int', 'class'):
        return 0.60
    if s == 'void':
        return 3.36
    if s == 'def':
        return -2.05
    if s in ('using', 'export'):
        return -0.85
    if word.startswith('//'):
        return -0.62
    if word == '#':
        return -0.32
    # Broad orthographic averages for initial tokens not covered above.
    for script, response in (
        ('Cyrillic', -0.40), ('Arabic', -0.20), ('Han', 0.11),
        ('Hangul', -0.30), ('Katakana', -0.35), ('Thai', -0.39),
    ):
        if regex.search(r'\p{Script=' + script + '}', word):
            return response
    if s.startswith(('"', "'")):
        return -0.27
    if s.startswith('/'):
        return 0.34
    if s.startswith(('_', '\\')):
        return -0.35
    if word.isascii() and word.isalpha():
        if len(word) == 1 and word.isupper():
            return 0.16
        if word.istitle():
            return 0.13
        return 0.06 if word.isupper() else -0.03
    return 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = int(prefix.token_ids[-1])
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, '')
    _, initial, same, tail = carry
    same = same and token == initial
    value = 0.0
    if same:
        value = start_value(s)
    elif s == '://':
        value = 0.20
    elif s == '、':
        value = 0.066
    elif s == r'\t':
        value = -0.06
    elif re.fullmatch(r'\\x[a-f]?', s):
        value = -0.10
    elif s in ('本站', '本网站'):
        value = -0.85
    elif s == '互联网':
        value = -1.20 if re.search('来源|来自|转载|归|所有', tail) else -0.12
    elif s == '上传' and re.search('网友|网络|来源', tail):
        value = -0.90
    elif s == '附件' and '下载' in tail:
        value = -1.0
    elif s == '资料' and '注册' in tail:
        value = -0.8
    elif s == '首页' and re.search('位置|收藏|本站', tail):
        value = -0.65
    elif s == 'IT':
        foreign = any(not c.isascii() and unicodedata.category(c)[0] == 'L'
                      for c in tail[-24:])
        value = -1.05 if foreign else 0.04
    elif s in ('给你', '给您', '给大家', '请大家'):
        value = -0.65
    elif s in ('电脑', '打包'):
        value = -0.45 if s == '电脑' else -0.70
    elif s == '考试':
        value = 1.05 if re.search('公务员|国家|准考证', tail) else 0.15
    elif s == '关键词':
        value = 1.33
    elif s == '观看' and '免费' in tail[-12:]:
        value = 0.85
    elif s == '完整' and '观看' in tail[-12:]:
        value = 0.5
    tail = (tail + s)[-64:]
    return (doc, initial, same, tail), value

"""A lexical/formatting pulse on the first token of an attention document.

Row beginnings count too, even when their text starts in mid-sentence. Headings,
indentation, definite articles and common sentence/code openings give the largest
pulses. Later tokens are approximated by zero. The small opening lexicons below
capture broad classes, not the remaining idiosyncratic lexical variation.
"""
READS = ()

# Lowercase grammatical words when the token includes a preceding space.
GRAMMAR = {
    'the': 9.35, 'of': 5.94, 'in': 6.29, 'with': 5.07, 'for': 4.68,
    'at': 4.72, 'to': 3.22, 'and': 3.18, 'or': 2.75, 'a': 3.10,
    'an': 2.51, 'on': 3.55, 'from': 3.56, 'by': 2.54,
    'my': 4.11, 'our': 4.51, 'your': 3.92, 'their': 4.15,
    'about': 3.45, 'including': 3.24, 'against': 6.8, 'after': 4.2,
    'across': 4.5, 'using': 7.5,
}


def opening_value(token):
    if token.startswith('<|'):
        return 0.0
    if token.isspace():
        if '\n' in token or '\r' in token:
            return 0.0
        if '\t' in token:
            return 10.5 if ' ' in token else (5.1 if len(token) > 1 else 0.0)
        if len(token) == 1:
            return 5.4 if token == ' ' else 2.3
        return 10.3 if len(token) == 2 else (13.3 if len(token) < 64 else 5.0)
    spaced = token.startswith(' ')
    word = token.strip()
    if word.startswith('/*'):
        return 4.0 if '\n' in token else 6.2
    if '\n' in token or '\r' in token:
        return 3.8 if word.startswith(('"""', "'''")) else 0.0
    if word == 'The':
        return 12.2 if spaced else 14.5
    if word in ('the', 'THE'):
        return (9.35 if spaced else 10.2) if word == 'the' else 7.0
    if word.lstrip('"“') == 'The':
        return 10.0
    if word and set(word) == {'#'}:
        return 14.8 if len(word) == 1 else (11.3 if len(word) == 2 else 13.3)
    if spaced and word.lower() in GRAMMAR:
        return GRAMMAR[word.lower()]
    if not spaced:
        if word == 'Are':
            return 14.0
        if word in ('Is', 'Can', 'Does'):
            return 10.4
        if word in ('In', 'At', 'Since', 'For', 'During', 'If', 'What'):
            return 8.0
        if word in ('When', 'Which', 'After', 'Although', 'My', 'Our',
                    'Your', 'Do', 'Have', 'Would', 'Could'):
            return 6.5
        if word in ('A', 'An', 'On', 'How', 'Why', 'From', 'Before',
                    'With', 'Because'):
            return 4.9
        if word in ('To', 'These', 'Will', 'Who', 'Where'):
            return 3.3
        if word in ('This', 'As'):
            return 2.0
        if word == 'Using':
            return 13.3
        if word in ('import', 'package'):
            return 10.95
        if word in ('from', 'using', 'use'):
            return 9.2
        if word in ('class', 'def', 'const', 'int', 'void', 'char',
                    'namespace', 'var', 'Use'):
            return 6.7
        if word in ('function', 'public', 'private', 'let', 'return'):
            return 3.4
        if word in ('a', 'an', 'of', 'in', 'to', 'and', 'or', 'if', 'unless'):
            return 3.0
    if word.startswith('#!'):
        return 5.2
    if word.startswith('#'):
        return 3.3 if word in ('#include', '#pragma') else 8.3
    if word and all(not c.isalnum() for c in word):
        if word in ('，', '。'):
            return 4.0
        if word.endswith(','):
            return 8.5
        if word.endswith('.'):
            return 3.2 if spaced else 5.7
        if word.startswith('//'):
            return 7.0
        if word in ('=', '+', '&', '&&', '=>'):
            return 4.4 if spaced else 1.5
        if word in ('-', '--'):
            return 5.0 if spaced else (3.5 if word == '-' else 6.6)
        if word in ('《', '【'):
            return 6.1
        if word == '(':
            return 4.5 if spaced else 5.4
        if word == ';':
            return 6.7
        if word == '*':
            return 6.0 if spaced else 3.6
        if word == '"':
            return 2.6 if spaced else 4.8
        if word == '\\':
            return 0.5 if spaced else -2.2
        if word == ':':
            return 1.4
        return 2.7
    if word.isdecimal():
        return 0.5 if word == '0' else -0.7
    return 0.3


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, opening_value(prefix.token_strings[-1]) if first else 0.0

programs.haiku:
"""layers.1.mlp.down_proj:1729 -- a "start of text" detector.

This component is silent everywhere except on the first token of a document. There it
fires strongly, and how strongly depends only on which token it is: tokens that open a
text or a line of code ("The", "#", indentation, "import", "package") fire hardest;
sentence-opening words, commas and prepositions fire moderately; mid-word fragments,
names, pronouns, digits and most other tokens barely fire.

A document starts at the first token of a row, and after every change of document id
(in the data a document ends with <|endoftext|>, so the token after it starts a new one).
The program: at a document start, look up the token's class and return its strength;
everywhere else return 0.
"""

READS = ()

# Tokens that most strongly open a text: "The", "#" (headers, comments), indentation.
STRONG = {"The", " The", "#", "##", "###"}
# Common openers: determiner "the", comma, code and sentence starters, question words.
OPENERS = {
    " the", "the", ",", "import", "package", "using", "Using", "from",
    "Are", "Is", "Does", "Can", "Do", "In", "If", "What",
}
# Mid-strength: punctuation and prepositions that begin a fragment of text.
MIDDLE = {".", "(", '"', "//", "/*", ";", ")", " of", " in", " for", " with", " on", " at", " from", " by", "A"}
# Weak: small function words.
WEAK = {" a", " and", " to", " or", " as", "a", "and", "to", "or", "as", "On"}


def token_strength(s):
    """How strongly a token, read as the first token of a document, fires."""
    if "�" in s or s.startswith("<|"):
        return 0.0
    core = s.strip()
    if core == "":  # whitespace only: a single space is weak, an indent run strong
        if s == " ":
            return 5.0
        if "\n" in s or "\r" in s:
            return 0.0
        return 12.0 if len(s) > 1 else 0.0
    if not s.isascii():
        return 0.0
    if s in STRONG or core in STRONG:
        return 14.0
    if core.isdigit():
        return -1.0
    if s in OPENERS or core in OPENERS:
        return 9.0
    if s in MIDDLE or core in MIDDLE:
        return 5.0
    if s.startswith(" ") and core.lower() in WEAK:
        return 3.0
    if s.startswith(" ") and core.isalpha():
        return 0.0  # a mid-sentence word with no sentence-opening role
    if not core[0].isalnum():
        return 0.0 if "\n" in s or "\r" in s or "\t" in s else 4.0
    if core[0].isupper() and core[1:].islower():
        return 2.0  # a capitalized word: sentence opener or name
    return 0.0


def step(carry, prefix, upstream):
    """Predict the component's activation at the newest token."""
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_doc:
        return carry, 0.0
    return carry, float(token_strength(prefix.token_strings[-1]))

programs.sol:
"""Approximate a response to code openings and body boundaries.

Import-like words get boosts after comments or code fences, adjusted by layout,
header distance and earlier imports. Declaration braces get larger values than
control-flow braces; Python function colons have a similar rule. Smaller rules
cover markup, headings, LaTeX braces, comment ends and source-file suffixes.
Unmatched tokens predict zero, apart from a negative document-start baseline.
Recent text, position and import count reset when the document changes.
"""
import math
import re

READS = ()
SOURCE_SUFFIXES = {
    '.py': .3, '.rs': .8, '.js': .7, '.java': -.2,
    '.scala': .7, '.h': -.1,
}
COMMENT_END = re.compile(
    r'(?:\*/|[\"\']{3}|'
    r'(?:#(?!include|define|pragma|if|else|endif|undef)|//)[^\n]*\n)'
)
CONTROL = re.compile(r'\b(?:if|else|for|while|switch|catch|try|finally|do)\b')


def predict(s, before, pos, imports):
    w = s.strip()
    b = before.replace('\\n', '\n').replace('\\t', '\t')
    line = b.rsplit('\n', 1)[-1]
    line_start = not line.strip()
    tab = s.startswith('\t')
    space = s[:1].isspace()
    semicolon = ';' in b[-100:]
    curly = '{' in b[-200:] or '}' in b[-200:]
    value = -.2 if pos == 0 else 0.0

    if w in ('import', '#include', 'include', 'from', 'package'):
        endings = list(COMMENT_END.finditer(b[-250:]))
        age = len(b[-250:]) - endings[-1].end() if endings else 1000
        near_header = math.exp(-age / 35)
        blank = bool(re.search(r'\n[ \t]*\n\s*$', b))
        fence = bool(re.search(r'```[^\n`]*\n\s*$', b))
        first = 1 / (1 + imports)
        if w == 'import':
            value += 1.1 - .5*space + 1.2*tab - .9*semicolon
            value += .6*curly + .6*first + .6*blank + 2.5*fence
        elif w in ('#include', 'include'):
            value += .4 - .65*space + .5*first + .8*blank + 2*fence
        elif w == 'from':
            value += -.05 + .9*line_start + 1.0*tab + .1*first
            value += 2.5*fence
        else:
            value += 1.1 - 1.2*space + .4*first + 1.5*fence
        if w != 'from' or line_start or tab or not space:
            value += 2.5*near_header
            if imports == 0 and age < 4:
                value += 2.5
        if pos == 0:
            value = {'import': -1.3, '#include': -.8,
                     'include': -.5, 'from': -.3, 'package': -2.1}[w]
    elif w in ('const', 'def', 'function', 'class', 'public', 'export'):
        base = {'const': .65, 'def': .4, 'function': .45,
                'class': .15, 'public': .35, 'export': .2}[w]
        value += base * (0.2 if space else 1.0)
        if tab:
            value += .6
        if line_start and not space:
            value += .25 if w != 'function' else .8
        if w == 'class' and semicolon:
            value += .35
        if w == 'public' and curly:
            value -= .15
    elif w == 'if':
        value += .07 - .09*space + .2*tab + .1*curly + .17*semicolon
    elif w == 'for':
        value += .15*tab
    elif w in ('using', 'use', 'namespace', 'extern', 'template'):
        if not space or tab:
            value += .3*line_start + .6*tab
        if pos == 0:
            value -= .6
    elif w.endswith('{') and set(w[:-1]) <= set('()') and w != '({':
        header = re.split(r'[{};]', b)[-1]
        declaration = bool(re.search(
            r'\b(?:class|struct|enum|interface|namespace|fn|func|function)\b',
            header,
        ))
        declaration |= bool(re.search(
            r'\b\w+[ \t]+\w+[ \t]*\([^{}]*\)\s*$', header,
        )) and not CONTROL.search(header)
        value += .09 + .24*('\n' in s) + .2*line_start
        if declaration and '\n' in s:
            value += .15
        elif CONTROL.search(b[-160:]):
            value -= .25
        if re.search(r'\\(?:begin|end)\s*$', b):
            value += 1.9
        if re.search(r'\bimport\s*$', b):
            value += .35
        if re.search(r'(?:=|return)\s*$', b):
            value -= .15
    elif '\n' in s and re.fullmatch(r'[)\]]*:', w):
        keywords = re.findall(
            r'\b(def|class|if|else|for|while|try|except|elif|with)\b',
            b[-200:],
        )
        kind = keywords[-1] if keywords else ''
        value += .45 if kind == 'def' else (.25 if kind == 'class' else -.04)
    elif w in ('<', '</'):
        value += .13 + .55*line_start
    elif w and set(w) == {'#'}:
        if line_start:
            value += -.8 if pos == 0 else (.28 if 2 <= len(w) <= 6 else 0)
    elif w.startswith('/*'):
        value += -.8 if pos == 0 else .2
    elif w.rstrip(';').endswith('*/'):
        value += .65 if '\n' in s else .05
    else:
        value += SOURCE_SUFFIXES.get(w, 0)
    if pos == 1 and before == '<?' and w == 'php':
        value += 4.5
    if pos == 1 and before == 'package' and w in ('com', 'org', 'net', 'io'):
        value += 2.7
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, before, imports = 0, '', 0
    else:
        _, pos, before, imports = carry
    s = prefix.token_strings[-1]
    value = predict(s, before, pos, imports)
    if s.strip() in (
        'import', 'from', '#include', 'include', 'package', 'using', 'use',
    ):
        imports += 1
    if '```' in s:
        imports = 0
    return (doc, pos+1, (before+s)[-600:], imports), float(value)

programs.haiku:
"""Code-start detector.

This component writes "source code begins here" into the residual stream. Read off its
strongest activations, it responds to:
- the keyword that opens a line of source code. On the first such line of a document it is
  strong: file headers (package, namespace, #include, <?php) about 4, import/from about 2,
  other keywords (def, class, function, const, var, ...) under 1. On later code lines of the
  same document it is weaker: import/from about 0.9, other keywords about 0.35;
- the opening brace of a LaTeX environment, the "{" of \\begin{ or \\end{ (about 2);
- a "<" that opens a line of markup (about 1.5);
- weakly, other opening braces (0.2) and source-file names such as .js, .py and /src (0.25);
- the first token of each document, slightly negative (-0.2).
Everywhere else it is near zero; the many small fluctuations are not modelled.
"""

CODE_KEYWORDS = {"import", "from", "package", "namespace", "using", "def", "class",
                 "function", "public", "pub", "func", "var", "let", "const", "#include", "php"}
HEADER_KEYWORDS = {"package", "namespace", "#include", "php"}
IMPORT_KEYWORDS = {"import", "from"}
LATEX_OPENERS = {"begin", "end"}
BRACES = {"{", "{\\"}
FILE_NAMES = {".js", ".py", ".rs", ".com", "/src", ".go", ".java", ".ts", ".cs", ".php"}
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    # where this document starts inside the row (rows pack several documents end to end)
    start = 0
    for k in range(len(prefix) - 1, 0, -1):
        if prefix.document_ids[k] != prefix.document_ids[k - 1]:
            start = k
            break
    if start == len(prefix) - 1:
        return (start, False), -0.2
    # carry: (document start, whether this document has already opened a line of code)
    seen_code = carry[1] if carry is not None and carry[0] == start else False
    before = prefix.token_strings[-2]
    line_start = before.endswith(("\n", "\t"))
    if word in CODE_KEYWORDS and (line_start or word == "import"):
        if not seen_code:
            if word in HEADER_KEYWORDS:
                value = 4.0
            elif word in IMPORT_KEYWORDS:
                value = 2.0
            else:
                value = 0.8
        else:
            value = 0.9 if word in IMPORT_KEYWORDS else 0.35
        return (start, True), value
    if word in BRACES:
        if before.strip() in LATEX_OPENERS:
            return (start, seen_code), 2.1
        return (start, seen_code), 0.2
    if word in FILE_NAMES:
        return (start, seen_code), 0.25
    if word == "<" and line_start:
        return (start, seen_code), 1.5
    return (start, seen_code), 0.0

programs.sol:
"""A German/Dutch article-versus-word-fragment contrast.

Completed words vote for a language using corpus frequencies. In German,
spellings much commoner as word beginnings than as complete words generally
get negative values. Open e-ending pieces at word beginnings are strongest;
capitals and interior endings are weaker. Most German articles, and Dutch de/het in Dutch
context, instead get positive estimates. This deliberately groups spellings,
missing exact fragment amplitudes and other lexical responses.
"""
from collections import defaultdict
from functools import lru_cache
from math import log10
import re
from wordfreq import top_n_list, zipf_frequency

READS = ()
VOWELS = frozenset('aeiouyäöü')
# (level inside a word, level at a word's beginning)
LEVELS = {
    'e': (-1.1, -3.6),
    'i': (-.4, -1.3),
    'a': (-1.9, -2.4),
    'other_vowel': (-.2, -.9),
    'liquid_nasal_h': (-.2, -1.4),
    'other_closed': (0., -.5),
    'no_vowel': (-.2, -.9),
    'multi_open': (-.4, -1.),
}
# (German-context level, capital extra, local level, local capital extra)
ARTICLES = {
    'der': (2., 1.4, .2, .6),
    'die': (1.4, .4, .2, 0.),
    'das': (2., -.5, .1, 1.4),
    'den': (1.5, .6, 0., -.1),
    'dem': (2.1, 1.2, -.1, 0.),
}

def clip(x, low=0., high=1.):
    return max(low, min(high, x))

# Prefix counts come from an ordinary word list, not component activations.
PREFIX_MASS = defaultdict(float)
for word in top_n_list('de', 50000):
    if word.isalpha():
        mass = 10**zipf_frequency(word, 'de')
        for end in range(1, min(len(word), 7)):
            PREFIX_MASS[word[:end]] += mass

@lru_cache(maxsize=100000)
def language_vote(word):
    if len(word) < 2 or not word.isalpha():
        return 0., 0.
    z = [zipf_frequency(word, lang)
         for lang in ('de', 'nl', 'en', 'fr', 'es', 'it', 'pt')]
    if max(z) < 3:
        return 0., 0.
    return (clip(z[0] - max(z[1:]), -2., 2.),
            clip(z[1] - max(z[:1] + z[2:]), -2., 2.))

@lru_cache(maxsize=50000)
def spelling(word):
    if (not word or len(word) > 6 or
        any(c not in 'abcdefghijklmnopqrstuvwxyzäöüßſ' for c in word)):
        return None, 0.
    mass = PREFIX_MASS.get(word, 0.)
    ratio = (log10(mass) if mass else 0.) - zipf_frequency(word, 'de')
    strength = clip(ratio - .5)
    groups = re.findall('[aeiouyäöü]+', word)
    vowels = sum(map(len, groups))
    category = None
    if not vowels:
        category = 'no_vowel'
    elif vowels == 1:
        if len(word) <= 4 and word[-1] in 'eia':
            category = word[-1]
        elif word[-1] in VOWELS:
            category = 'other_vowel'
        else:
            category = 'liquid_nasal_h' if word[-1] in 'lmnrh' else 'other_closed'
    elif word[-1] in VOWELS and len(groups[-1]) == 1:
        category = 'multi_open'
    return category, strength

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        german, dutch, unfinished = 0., 0., ''
    else:
        _, german, dutch, unfinished = carry
    text = prefix.token_strings[-1]
    previous = unfinished if text and text[0].isalpha() else ''
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', text):
        if part.isalpha():
            unfinished += part
        elif unfinished:
            a, b = language_vote(unfinished.lower())
            german = clip(.88*german + a, -8., 8.)
            dutch = clip(.88*dutch + b, -8., 8.)
            unfinished = ''
    word = text.strip().lower()
    capital = bool(text.strip() and text.strip()[0].isupper())
    g, ga, d = clip((german-1.)/5.), clip((german+1.)/5.), clip((dutch+1.)/5.)
    category, strength = spelling(word)
    value = 0.
    if category is not None:
        inside, initial = LEVELS[category]
        level = inside if previous else initial
        if capital:
            level += 1.3 if category == 'e' else (.7 if category == 'no_vowel' else .5)
        if category == 'e':
            level -= word[0] in 'fhsvzlmnrw'
            level += .5 * bool(previous and previous[-1].lower() in VOWELS)
        value = g * strength * level
    if word in {'be', 'ge', 'ver', 'er', 'ent', 'zer'}:
        value += .7*g
    if word in ARTICLES:
        a, cap, local, local_cap = ARTICLES[word]
        value += ga*(a + cap*capital) + local + local_cap*capital
    elif word == 'het':
        value += 4.9*d - 1.6*ga + .5 + .7*capital
    elif word == 'de':
        value += 1.9*d - ga*(1. + .7*capital)
    return (doc, german, dutch, unfinished), value

"""Approximate a spelling-continuation signal in Japanese and Thai.

Short kana that extend a dictionary Japanese verb after kanji are positive.
Particles are weak; several auxiliary and demonstrative fragments are negative.
Thai consonant fragments are negative, less so after a vowel/tone mark.
Closing a tool call has a separate negative response. These are local spelling
heuristics, not a complete Japanese or Thai morphological analysis.
"""
from functools import lru_cache
import unicodedata
import regex
import jmdict

READS = ()
PARTICLES = frozenset('はのをにでとがもやへな')
THAI_CONSONANTS = frozenset(
    'กขฃคฅฆงจฉชซฌญฎฏฐฑฒณดตถทธนบปผฝพฟภมยรลวศษสหฬอฮ'
)
THAI_SONORANTS = frozenset('งญณนมยรลวฬ')
# a/i/u/e/o grades of consonant-stem Japanese verbs.
GRADES = ('わいうえお', 'かきくけこ', 'がぎぐげご', 'さしすせそ',
          'たちつてと', 'なにぬねの', 'ばびぶべぼ', 'まみむめも',
          'らりるれろ')
SPECIAL = {'</tool_call>': -1.82, '<tool_response>': -0.33,
           '</tool_response>': 0.20, '<|im_end|>': -0.09}


@lru_cache(maxsize=16384)
def verb(word):
    return any(g.startswith('to ') for g in jmdict.glosses(word))


@lru_cache(maxsize=16384)
def verb_ending(kanji, kana):
    """Recognize a whole verb, an unfinished stem, or an inflected ending."""
    for n in range(1, len(kanji) + 1):
        word = kanji[-n:] + kana
        if verb(word):
            return 'whole'
        # 生か -> 生かす, 重ね -> 重ねる.
        if any(verb(word + end) for end in 'うくぐすつぬぶむる'):
            return 'stem'
        # 読み -> 読む, 取り -> 取る.
        for row in GRADES:
            if word[-1] in row and verb(word[:-1] + row[2]):
                return 'inflected'
    return None


@lru_cache(maxsize=8192)
def script(token):
    if regex.fullmatch(r'\p{Hiragana}+', token):
        return 'kana'
    if regex.fullmatch(r'\p{Thai}+', token):
        return 'thai'
    return 'other'


def predict(token, left):
    kind = script(token)
    if kind == 'kana':
        if token in ('そう', 'そうです'):
            return -3.0
        if token == 'いた':
            return -1.4
        if token in ('って', 'った', 'んで', 'んだ',
                     'れて', 'れた', 'えて', 'えた'):
            return 1.4
        if len(token) <= 2 and token not in ('する', 'した', 'して'):
            match = regex.search(r'(\p{Han}{1,3})$', left)
            form = verb_ending(match[1], token) if match else None
            if form:
                if len(token) == 2:
                    return 1.2
                return {'whole': 1.3, 'stem': 2.5, 'inflected': 2.2}[form]
        if len(token) == 1:
            if token in PARTICLES:
                return 0.03
            if token in 'あこそど':  # demonstrative/interrogative stems
                return -1.5
            if token in 'まつたっだ':  # auxiliary/copula fragments
                return -0.9
            return -0.15
        return 0.03
    if kind == 'thai':
        consonants = sum(c in THAI_CONSONANTS for c in token)
        if len(token) == 1 and consonants:
            after_vowel = left and (
                unicodedata.category(left[-1]) in ('Mn', 'Mc') or left[-1] == 'า'
            )
            if after_vowel:
                return 0.1 if token in THAI_SONORANTS else -0.9
            return -2.25
        if consonants and all(c in THAI_CONSONANTS or
                              unicodedata.category(c) == 'Mn' for c in token):
            return -0.29
        return -0.21
    return SPECIAL.get(token, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_strings[-1]
    left = old.decode('utf-8', errors='ignore')[-10:]
    value = predict(token, left)
    return (doc, (old + prefix.token_bytes[-1])[-48:]), value

programs.haiku:
"""Layer-1 MLP neuron 1732 (component layers.1.mlp.down_proj:1732 reads only this neuron).

It fires on Japanese verb and adjective stems: a hiragana okurigana (the kana that
follows a kanji and precedes an inflection, as in 植え, 走り, 支え, 積む, 知り) is strongly
positive, and most so when it directly follows a kanji. Particles and other kana stay near
zero. It is negative on Thai letters (most strongly on consonants), and on the closing
</tool_call> tag of tool-call transcripts. Everything else is 0.
Values are mean activations per class, fitted on training rows.
"""
import unicodedata

READS = ()

THAI_LETTER = -0.87
THAI_MARK = -0.19
TOOL_CLOSE = -1.85
VERB_KANA = {"え", "び", "か", "め", "ら", "り", "み", "む", "き", "く", "し", "す", "る", "い", "わ", "ね", "う", "じ",
             "って", "った", "んで", "して", "えて", "めて", "えた"}
KANA_AFTER_KANJI = 2.2
KANA_OTHER = 0.24


def _is(ch, word):
    try:
        return word in unicodedata.name(ch)
    except ValueError:
        return False


def _all(s, word):
    return len(s) > 0 and all(_is(c, word) for c in s)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev = "" if new_doc else prefix.token_strings[-2]
    if tok == "</tool_call>":
        return None, TOOL_CLOSE
    if tok and _is(tok[0], "THAI"):
        return None, THAI_LETTER if unicodedata.category(tok[0]) == "Lo" else THAI_MARK
    if tok in VERB_KANA:
        if prev and _all(prev, "CJK"):
            return None, KANA_AFTER_KANJI
        return None, KANA_OTHER
    return None, 0.0

programs.sol:
"""A local phrase detector, chiefly for expository English.

'We have', 'this study/problem', and 'such that' give positive pulses.
'As follows/shown' and 'so as' give negative ones. Copulas, sentence case,
and nearby mathematical notation adjust their size. A few conventional
code constructions and document-opening imports have separate signals.
Unmatched text is near zero; this does not model its token-specific variation.
"""
import re

READS = ()
MATH = re.compile(r'[$=^_\\]|[α-ωΑ-Ω≤≥∈∑]')
MODALS = {'can', 'could', 'may', 'might', 'would', 'should', 'must'}
COPULAS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, recent, pos = '', '', '', 0
    else:
        _, previous, before, recent, pos = carry
    token = prefix.token_strings[-1]
    word, prev = token.strip().lower(), previous.strip().lower()
    prior = before.strip().lower()
    value = 0.003

    if word == '如下':  # Chinese 'as follows'.
        value = -1.8
    elif word == 'follows' and prev == 'as':
        value = -1.6 if prior in COPULAS else -3.1
    elif word == 'shown' and prev == 'as':
        value = -0.6 if previous.strip() == 'As' else -1.05
    elif word == 'as' and prev == 'so':
        value = -0.4 if ',' in before else -0.85
    elif word == 'have' and prev == 'we':
        if pos == 1:
            value = 1.8
        elif MATH.search(recent):
            value = 1.2
        elif prior in {'hence', 'thus', 'then', 'therefore'}:
            value = 1.5
        elif prior == 'that':
            value = 0.27
        else:
            value = 0.6
    elif word == 'have' and prev in {'i', 'you'}:
        value = 0.12
    elif word == 'study' and prev in {'this', 'present', 'current', 'our'}:
        value = 0.5
        if prev == 'present':
            value = 1.0
        elif previous.strip() == 'This':
            value = 0.92
        elif before.strip() == 'In':
            value = 1.15
        elif prior == 'of':
            value = 0.33
    elif word == 'problem' and prev == 'this':
        value = 0.5
        if prior == 'in':
            value = 2.2 if before.strip() == 'In' else 1.3
        elif previous.strip() == 'This':
            value = 1.8
    elif word == 'question' and prev == 'this':
        value = 0.7 if previous.strip() == 'This' else 0.35
    elif word == 'results' and prev == 'these':
        value = 0.55 if previous.strip() == 'These' else 0.1
    elif word == 'that' and prev == 'such':
        value = 0.65 if MATH.search(recent) else 0.2
    elif word == 'be' and prev in MODALS:
        value = 0.10
    elif token == ' -' and previous.endswith('@@'):
        value = -1.05
    elif token == '.util' and prev == 'java':
        value = 0.38
    elif word == 'import' and previous.endswith(';\n'):
        value = -0.17
    elif pos == 0 and token in {'package', '#include', 'use'}:
        value = 1.6
    elif pos == 0 and token in {'import', 'using'}:
        value = 0.45
    elif pos == 0 and token.isspace():
        value = 0.4

    recent = (recent + token)[-120:]
    return (doc, token, previous, recent, pos + 1), value

"""A partial, spelling- and context-based approximation.

Positive responses cover source-code receivers/member access, GitHub and dependency
paths, goal words, some web-interface labels, Romance-language negation, and short
vowel-first word fragments. Ordinary 'self' is negative, unlike code receivers.
There is also a negative document-start offset. Context resets per document.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('es', 'it', 'fr', 'pt')
_CODE = re.compile(
    r';|=>|(?:this|self)\.|(?:^|\n)[ \t]{3,}'
    r'|\b(?:def|class|function|import|return|const|let|var) |//'
)
# These are spelling patterns, not a claim that the fragments are whole words.
_FRAGMENT = re.compile(r'[aou](?:[bfghjkvwyz]|ph|ng|ff)\Z')


@lru_cache(maxsize=32768)
def language_evidence(word):
    english = zipf_frequency(word, 'en')
    return tuple(zipf_frequency(word, lang) - english for lang in LANGUAGES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        tail, code, pending, scores = '', 0.0, '', (0.0,) * 4
    else:
        _, tail, code, pending, scores = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    # Finish words as their closing punctuation or whitespace arrives. Language
    # evidence is a decaying comparison of their dictionary frequencies.
    for ch in text:
        if ch.isalpha():
            pending = (pending + ch.lower())[-40:]
        else:
            if len(pending) >= 2:
                evidence = language_evidence(pending)
                scores = tuple(max(-15.0, min(15.0, 0.85 * s + e))
                               for s, e in zip(scores, evidence))
            pending = ''
    spanish, italian, french, portuguese = scores
    boundary = text[:1].isspace() or not tail or not tail[-1].isalnum()
    code *= 0.97
    if _CODE.search(tail[-35:] + text):
        code = 1.0
    value = 0.0
    if not boundary and 1 <= len(word) <= 4 and word.isalpha():
        spelling = anyascii(word).lower()
        if _FRAGMENT.fullmatch(spelling):
            value = 0.25
    if word == '.com' and tail.lower().endswith('github'):
        value = 0.22 if tail.lower().endswith('.github') else 1.75
    elif word == '_modules' and tail.endswith('node'):
        value = 0.93
    elif word in ('this', '(this'):
        if word.startswith('(') or boundary:
            immediate_code = (
                re.search(r'[ \t]{2,}$', tail)
                or re.search(r'(?:\b(?:return|await|yield)|[=+(]|&&|\|\|)$',
                             tail.rstrip())
            )
            if not text.startswith(' ') or immediate_code:
                value = 0.95
            elif tail.rstrip().endswith('//'):
                value = 0.75
            else:
                value = 0.03
    elif word in ('self', '(self'):
        if word.startswith('('):
            line = re.split(r'\n|\\n', tail)[-1]
            value = -0.1 if 'def ' in line else 0.55
        elif not boundary:
            value = -0.25
        elif code > 0.2:
            value = 0.15 if tail.rstrip().endswith(('(', '&')) else 0.75
        else:
            value = -0.20
    elif word == '->' and tail.rstrip().endswith('this'):
        value = 1.4
    elif word.lower() in ('goal', 'goals', '.goal'):
        value = 1.25 if word.startswith('.') else 0.95
    elif word.lower() == 'não':
        value = 0.75
    elif word.lower() == 'non':
        if italian > max(0.5, french, portuguese):
            value = 0.9
        elif french > max(0.5, portuguese):
            value = 0.45
    elif word.lower() == 'no':
        if max(spanish, italian) > max(0.5, french, portuguese):
            value = 0.95
    elif word == 'permalink':
        value = 0.9
    elif word == 'Tags' and tail.rstrip().endswith('Show'):
        value = 1.3
    elif word == 'Solution':
        value = 0.60 if tail.rstrip().endswith(('Text', 'Video')) else 0.04
    elif len(word) >= 2 and set(word) == {'·'}:
        value = 0.46
    if first:
        value = -0.44
    return (doc, (tail + text)[-160:], code, pending, scores), value

"""A sparse approximation of lexical completions and opening artifacts.

Recognizes test-result phrases, tryout compounds, rulemaking phrases, 株,
and a few signed split words. Most other tokens get zero. Document openings
use a rough whitespace/word-shape estimate, with separate layout-artifact
values; it persists through an initial run of the identical token. A bounded
byte tail recognizes split UTF-8 characters. The long tail of other individual
collocations is deliberately left unexplained.
"""
import re

READS = ()
OPENING_LAYOUT = {
    '<!': -9.66,       # markup declaration opener
    '//\n': -5.9,      # source-file comment header
    '\r': -5.38,      # bare carriage return
    '··': -1.36,       # repeated decorative separators
    '^^^^': -2.67,
}
# These responses apply only when the expression crosses a token boundary.
COMPOUNDS = {
    '评语': 2.3,       # review/comment
    '沿街': 2.4,       # along the street
    '住建': 0.7,       # housing/construction
    '投建': 1.0,       # invest in construction
    '试剂': 1.3,       # chemical reagent
    '計画': -1.1,      # plan (Japanese)
    '撮影': -1.2,      # photography (Japanese)
    '静か': -0.95,     # quiet (Japanese)
    '予想': -1.4,      # expectation (Japanese)
}
# Trial/tryout completions, including Japanese sporting matches (試合).
TRYOUT_ENDINGS = {
    '穿', '驾', '乘', '药', '行', '生产', '作品', '合', '读', '玩',
}


def opening_value(token):
    if token in OPENING_LAYOUT:
        return OPENING_LAYOUT[token]
    if token.isspace():
        if '\r\n' in token:
            return -1.63
        if token == ' ':
            return -0.08
        return -0.2 if token.count('\n') > 1 else -0.85
    if token.startswith('<|'):
        return -0.3
    if token.startswith(' ') and token.strip().isalpha():
        return -0.22
    if token[:1].isupper() and token.endswith('ing'):
        return 0.2
    return -0.4


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        first, opening, tail = raw, True, b''
    else:
        _, first, opening, tail = carry
        opening = opening and raw == first
    before = tail.decode('utf-8', 'ignore')
    text = (tail + raw).decode('utf-8', 'ignore')
    current = raw.decode('utf-8', 'ignore')
    value = opening_value(prefix.token_strings[-1]) if opening else 0.0
    if text.endswith('株') and len(current.strip()) <= 1:
        value = 2.3 if before[-1:].isnumeric() else 3.9
    elif not opening:
        if current == '式' and before.endswith('株'):
            value = 1.65
        for expression, response in COMPOUNDS.items():
            if text.endswith(expression) and not current.endswith(expression):
                value = response
                break
        # Trial actions and common motion, risk, county, and practice compounds.
        previous_token = prefix.token_strings[-2]
        if previous_token in ('试', '試') and current in TRYOUT_ENDINGS:
            value = 1.3
        if current == '行' and before.endswith(tuple('限渐住履穿随遊游潜')):
            value = 0.75
        if current == '險' and before.endswith(tuple('避冒探')):
            value = -0.8
        if current == '县' and before.endswith(tuple('随撤')):
            value = 0.8
        if current == '践' and before.rstrip().endswith(('实', '実')):
            value = -0.9
        match = re.search(r'([a-z]+)[ -]*$', before.lower())
        previous = match[1] if match else ''
        word = current.lower().strip(' -')
        if word in ('positive', 'positives', 'negative', 'negatives'):
            if previous in ('test', 'tested', 'testing'):
                value = 3.8
            elif previous in ('true', 'false'):
                value = 2.7
        if word == 'rule' and previous in ('proposed', 'interim', 'final'):
            value = 1.2 if previous == 'interim' else 2.3
        if word in ('box', 'boxes') and previous in ('gift', 'kick', 'search'):
            value = 0.9
    return (doc, first, opening, (tail + raw)[-64:]), value

"""Approximate a line-ending feature, strongest at chat-message boundaries.

Return zero away from newline tokens. At line endings, distinguish blank
lines, whitespace and punctuation; the first few line endings are generally
more negative than later ones. Newlines after message markers, role labels,
and tool/thought tags get large negative values, especially after tool messages.
There is a small additional negative offset in chat documents. A newline
at the very first token is an exception with a positive estimate. Counters
reset on document changes. Finer formatting and lexical effects are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        breaks, position, chat = 0, 0, False
    else:
        _, breaks, position, chat = carry
    previous = older = ''
    if position:
        previous = prefix.token_strings[-2]
    if position > 1:
        older = prefix.token_strings[-3]
    chat = chat or text == '<|im_start|>'
    value = 0.0
    if '\n' in text:
        core = text.strip()
        multiple = text.count('\n') > 1
        novelty = 1.0 / (breaks + 1)
        if previous == '<|im_end|>':
            value = -2.54 if older == '</tool_response>' else (
                -2.40 if older == '</tool_call>' else -2.0
            )
        elif previous == '<tool_call>':
            value = -1.95
        elif previous == '<tool_response>':
            value = -1.75
        elif previous in ('assistant', 'user', 'system', 'tool'):
            value = -0.98 if multiple else -1.38
        elif previous in ('<think>', '</think>'):
            value = -1.20
        else:
            if text == '\n':
                value = -0.10 - 0.52 * novelty ** 2
            elif text == '\n\n':
                value = -0.18
            elif not core:
                value = -0.02 - 0.20 * novelty
            elif core[-1:] in '.!?。！？':
                value = -0.10 if multiple else 0.38 - 0.83 * novelty
            elif core[-1:] in ':：':
                value = -0.03 if multiple else 0.12 - 0.55 * novelty
            elif core[-1:] in '([{':
                value = -0.20
            elif core[-1:] in ')]}':
                value = 0.00 if multiple else 0.06 - 0.44 * novelty ** 2
            if chat:
                value -= 0.15
            if position == 0 and not core:
                value = 0.75
            elif position == 0 and not multiple and core in ('.', ':'):
                value = 0.95
        breaks += 1
    return (doc, breaks, position + 1, chat), value

programs.haiku:
"""Layer 1, MLP down-projection, component 1737: a first-token-of-document feature.

Inside a document this component is almost silent: its activation is near zero at every
token after the first. Only at the first token of each document (position 0 of a row, or
the first token after a document boundary) does it take a value. That value depends on
the word alone, because the first token attends only to itself, so it is a word-level
feature with a rough meaning axis:

- strongly positive (about +8) for operation verbs of software and maths (add, select,
  subtract, divide, cancel, join, split, translate ...);
- positive (about +3 to +6) for month names, a few modals (may, should, must, whether),
  and math and code symbols (" .", " |", " +", " /", "√");
- strongly negative (about -7) for nouns about people, the body, health, food, money,
  files, and everyday or technical things (person, people, speaker, patient, car, data,
  system, file, problem ...);
- about -6.5 for first names (David, Robert, Tim, Steve ...);
- about -5 for adjectives and adverbs (new, high, long, better, very, actually ...);
- about -3.5 for determiners, possessives and quantifiers that begin a noun phrase (the,
  of, for, this, your, their, some, many ...);
- -10 for the end-of-text marker and about -0.3 for the chat-start marker;
- about -1.6 for any other word.

Everything else in a document is predicted as 0.

The word lists are the concepts; the values are roughly the average activation of each
class over the training data. On the eval rows this explains about 30% of the variance,
against 22% for predicting one constant at document starts. What the short program omits
is the idiosyncratic value of each of the many other words, which a table of per-word
values would add (up to about 94% of the variance at document starts).
"""

READS = ()

PEOPLE_AND_THINGS = set(
    """person people persons speaker patient patients teacher chef student students player players
    doctor nurse man men woman women child children kid kids customer user users time file files
    field fields team body car cars game games water hotel farm paper book books medical disease
    company city house food money music animal animals data system systems test function functions
    work day days case point way video method process result results object film business life art
    health workspace history world year years thing things place home school job name names value
    values problem code effect part term terms side path study energy light language surface face
