"""A negative start-of-context pulse, sustained while the first token repeats.

Its size depends on token type. For Latin word pieces, longer and rarer
pieces receive larger negative pulses; leading spaces and case adjust this.
Whitespace, numbers and punctuation have separate, generally smaller pulses.
After the initial repeated token ends, predict zero, ignoring small residuals.
"""
import math
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()


def pulse(text):
    s = text.strip()
    if not s:
        if text == ' ':
            return -2.85
        if '\n' in text:
            return -6.5 if text.count('\n') == 1 else -3.8
        return -12.0 if '\t' in text else -10.0
    if s.startswith('<|') and s.endswith('|>'):
        return -18.2 if s == '<|im_start|>' else -14.5
    if s.isdecimal():
        return -8.7
    if '\ufffd' in s:
        return -12.0  # Incomplete UTF-8 character at a token boundary.
    if regex.fullmatch(r'[\p{Script=Latin}\p{M}]+', s):
        value = (-16.6 - 2.1 * math.log1p(len(s))
                 + 0.77 * zipf_frequency(s, 'en'))
        if text.startswith(' '):
            value += 1.5
        if s.istitle():
            value -= 0.6
        if s.isupper():
            value += 0.8
        return value
    if regex.fullmatch(r'\p{Script=Han}+', s):
        return -13.4
    if all(unicodedata.category(c)[0] in 'PS' for c in s):
        size = 8.5
        if all(c in '.!?。？！' for c in s):
            size = 4.9
        elif all(c in ',;:，；：()[]{}（）【】' for c in s):
            size = 5.7
        elif '#' in s:
            size = 11.3
        elif all(c in "'\"`‘’“”" for c in s):
            size = 7.7
        elif all(c in '=+-*/<>_%&|~^\\' for c in s):
            size = 7.3
        return -size - min(len(s) - 1, 4)
    return -15.3


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, pulse(prefix.token_strings[-1]))
    elif token != carry[1]:
        carry = (doc, None, 0.0)
    return carry, carry[2]

