import re

READS = ()
MATH = re.compile(
    r'[$=±√∑∫²³≥≤≠]|\\(?:frac|sum|int|begin|math)|'
    r'\b(?:theorem|lemma|proof|triangle|equation|polynomial|matrix|integer|'
    r'variable|function|quadratic|sequence|coordinates|slope|radius|prime|'
    r'interval|determinant|eigenvector|vector|linear|algebra|dimension|'
    r'rotation|permutation|definition|derivative)\b',
