"""Approximate a response to explicit whitespace and padding fragments.

Negative cases include space-only strings/groups, indentation after a written
backslash-n or a printed source line number, mixed ordinary/nonbreaking spaces,
spaced backtick runs, and inline hash comments. Smaller rules cover spacing
around parentheses, commas, contractions and real newlines, and control
characters. Most text is near zero; document starts have a positive bias.
"""
import re
import unicodedata

READS = ()
_WRITTEN_NEWLINE = re.compile(r'\\n *$')
_NUMBERED_LINE = re.compile(r'(?:^|\n) *[0-9]+\t *$')
# Matching delimiters around a space-only group or string.
_EMPTY_GROUPS = {
    '(': (')', -2.7),
    '[': (']', -2.7),
    '{': ('}', -3.5),
    '"': ('"', -1.4),
    "'": ("'", -2.4),
}
_CONTRACTION_ENDINGS = {'s', 't', 're', 've', 'll', 'd', 'm'}


def predict(s, previous, tail, blank, first):
    core = s.lstrip(' ')
    letter = core[:1].isalpha()
    spaces = len(s) - len(core)
    last = tail[-1:]
    if first:
        if letter:
            return 0.46 if spaces else 0.65
        return 0.32
    if spaces and last in _EMPTY_GROUPS:
        closer, value = _EMPTY_GROUPS[last]
        if core.startswith(closer):
            return value
    if spaces and last in ("'", '’') and core in _CONTRACTION_ENDINGS:
        return -0.8
    if spaces == 1 and last == '\n' and '\n' in s and s.isspace():
        return -0.65
    if spaces >= 8 and s.isspace() and _NUMBERED_LINE.search(tail):
        return -1.5
    if _WRITTEN_NEWLINE.search(tail):
        if spaces >= 2:
            if spaces <= 3:
                return -1.5 if previous.strip() == 'n' else -0.9
            return -0.8
        if not spaces:
            return -0.03
        if letter:
            return -0.42 if len(previous) <= 1 else 0.0
        return -0.4
    if '\xa0' in s:
        if last == ' ':
            return -1.05
        if spaces:
            return -1.44 if last == '\xa0' else -0.37
        return -0.015
    if core.startswith('`'):
        if last == '\xa0':
            return -0.55
        return -1.13 if last == '`' and ' ' in previous else -0.04
    if any(unicodedata.category(c) == 'Cc' and c not in '\n\r\t' for c in s):
