    if core.startswith('#') and previous == ' ' and not blank:
        return -3.6
    if spaces and last == '(':
        if letter:
            return -0.19 if len(s) <= 5 else -0.9
        return -0.5 if core.startswith(('(', '[', '{')) else -0.9
    if spaces and core.startswith(','):
        return -0.24
    if last == '\n' and spaces and not s.isspace():
        return -0.43 if core[:1].isupper() else -0.1
    if spaces >= 2 and last in ('"', '“', '‘'):
        return -0.8
    return 0.002


