    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail, blank = ('', '', True) if first else carry[1:]
    s = prefix.token_strings[-1]
    value = predict(s, previous, tail, blank, first)
    if '\n' in s:
        blank = not s.rsplit('\n', 1)[1].strip()
    elif s.strip():
        blank = False
    return (doc, s, (tail + s)[-64:], blank), value

