"""Approximate a token-shape and Han word-boundary signal.

Document-initial responses depend strongly on script and token length.
Elsewhere, two-Han-character tokens get a boost when a common word crossing
from the left ends at their FIRST character, not at the token's end. This
uses corpus word frequencies, not a table of model token identities. A
separate correction handles reduplication of the initial character.
The rules capture average tendencies, not the individual large spikes.
"""
from functools import lru_cache
from math import log10
import regex
from opencc import OpenCC
from wordfreq import get_frequency_dict

READS = ()
REDUPLICATION = 1.0
FREQUENCIES = get_frequency_dict('zh')
SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=40000)
def frequency(word):
    """Log corpus frequency on the Zipf scale; unseen words have score zero."""
    word = SIMPLIFY.convert(word)
    return max(0.0, 9.0 + log10(FREQUENCIES.get(word, 1e-9)))


def initial_response(text, han, east_asian):
    length = len(text)
    if han:
        return -0.44 if length == 1 else -0.74
    if east_asian:
        return 0.10 if length == 1 else -0.40
    if text.isascii() and text.isdigit():
        return 0.47
    if text.isascii() and text.isalpha():
        if length == 1:
            return 0.24
        if length <= 3:
            return 0.08
        return -0.10 - 0.05 * (min(length, 8) - 4)
    if text and regex.fullmatch(r'[^\w\s]+', text):
        return 0.24
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    tail, previous = (b'', '') if first else carry[1:]
    text = prefix.token_strings[-1].strip()
    han = bool(regex.fullmatch(r'\p{Han}+', text))
    east_asian = bool(regex.fullmatch(
        r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}ー]+', text))
    value = (0.009 if len(text) == 1 else -0.03) if han else 0.0

    if first:
        value = initial_response(text, han, east_asian)
    elif han and len(text) == 2:
        # Joining bytes repairs characters split across tokenizer tokens.
        left_text = tail.decode('utf-8', 'replace').rstrip()
        match = regex.search(r'\p{Han}{1,3}$', left_text)
        left = match.group() if match else ''
        if '\ufffd' in previous:
            previous = left[-1:]
        short = max((frequency(left[-n:] + text[0])
                     for n in range(1, len(left) + 1)), default=0.0)
        whole = max((frequency(left[-n:] + text)
                     for n in range(1, len(left) + 1)), default=0.0)
        word = frequency(text)
        if short - whole > 3.25:
            if len(previous) == 1:
                value = 0.35 if frequency(text[-1]) < 5.5 else 0.09
            else:
                value = 0.09 if word < 5.0 else -0.025
        else:
            value = -0.04 if short - word < -2.5 else 0.01
        if previous == text[0]:
            value += REDUPLICATION

    tail = (tail + prefix.token_bytes[-1])[-36:]
    return (document, tail, text), float(value)

