"""Row-start predictor: the component's activation at the first token of a row (no context yet)
is negative when that token is a Chinese character or word, and mildly positive otherwise.
Zero at every later position."""

READS = ()


def _has_cjk(s):
    return any("一" <= c <= "鿿" for c in s)


def step(carry, prefix, upstream):
    if prefix.position != 0:
        return carry, 0.0
    tok = prefix.token_strings[-1]
    return carry, (-0.4 if _has_cjk(tok) else 0.03)

