"""Approximate a y-spelling feature, strongest in short fragments.

Transliteration extends the spelling rule beyond Latin. Lowercase pronouns,
-ly/-ity endings and non-Latin spellings receive separate adjustments.
A y can also persist through the rest of a Latin word, fading with distance.
The -ies/-ied inflections, y-shaped Cyrillic у and non-Latin i-like
vowels also respond. Layout marks and document starts are modeled separately.
"""
import math
from functools import lru_cache
from anyascii import anyascii

READS = ()
PRONOUNS = {
    'you', 'your', 'yours', 'yourself', 'yourselves', 'my', 'myself',
    'they', 'them', 'their', 'theirs',
}

@lru_cache(maxsize=20000)
def spelling_value(s):
    word = ''.join(c for c in anyascii(s).lower() if c.isalpha())
    n = max(1, len(word))
    root = math.sqrt(n)
    spaced = bool(s and s[0].isspace())
    foreign = any(ord(c) > 127 for c in s)
    value = 0.0111
    if 'y' in word:
        value += -0.2826 + 2.0081 / root
        if spaced:
            value += 0.3518 - 0.3245 / root
        else:
            value += 0.4214 / math.sqrt(max(1, n - 2))
        if s.strip()[:1].isupper():
            value += 0.1281
        if foreign:
            value -= 0.0463 + 1.0744 / root
        if spaced and s.strip() in PRONOUNS:
            value -= 0.5726
        if word.endswith('ly'):
            value -= 0.1785
        if word.endswith('ity'):
            value -= 0.1596
    if word.endswith(('ies', 'ied')):
        value += 1.4393 / root
    if '#' in s:
        value += 0.4961
    if s.count('.') >= 4 and not word:
        value += 0.4624
    if s == '    ':
        value += 1.2114
    if '\xa0' in s:
        value += 0.1638
    if spaced and s.strip().lower() == 'у':  # Cyrillic y-shaped letter
        value += 1.2442
    if word in {'i', 'ui'} and foreign:
        if not any(c.isascii() and c.isalpha() for c in s):
            value += 0.2536
    return value, word


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous_word = '' if initial else carry[1]
    value, letters = spelling_value(s)
    if not s or not (s[0].isascii() and s[0].isalpha()):
        previous_word = ''
    if 'y' in previous_word and 'y' not in letters and letters:
        distance = min(10, len(previous_word) - previous_word.rfind('y') - 1)
        strength = max(0.0, 1.2087 - 0.1966 * distance)
        value += strength / math.sqrt(len(letters))
    word = (previous_word + letters)[-32:]
    if not s or not (s[-1].isascii() and s[-1].isalpha()):
        word = ''
    if initial:
        value -= 0.5606
        if letters:
            value -= 0.7300
        if s.strip().isdigit():
            value += 0.2971
    return (doc, word), float(value)

programs.haiku:
"""Layer-1 MLP component 1744 (of layers.1.mlp.down_proj): a detector for the letter "y".

The component reads the MLP's hidden activations and writes into the residual stream. Its
activation is large when the token being read contains the letter y (or Y), and near zero
otherwise. Levels:
  - a token that is just the letter y (the "y" of "Sc|y|phomedus", "p|y|3", a bare y as a
    variable): strongest, about 2.0;
  - a common English word spelled with y ("by", "any", "may", "only", "day", "very", "why",
    "study", "many", "my", "you", "they"): about 0.9;
  - a short fragment of a word with y (2 to 3 letters: "py", "ty", "ry", "ys", "-y"): about 1.2;
  - any other token containing y (longer words and names such as "country", "Yale"): about 0.7;
  - every token without y: about 0.

The program is stateless: it looks only at the newest token.
"""

READS = ()

# Common English words containing y, read as whole words.
Y_WORDS = frozenset(
    "by any may only day days very why try study studies year years many way my you "
    "your they type key today body dry yet young youth ay ey ly".split()
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if "y" not in word:
        return None, 0.0
    if word == "y":
        return None, 2.0
    if word in Y_WORDS:
        return None, 0.9
    if len(word) <= 3:
        return None, 1.2
    return None, 0.7

programs.sol:
"""Approximate a formatting-sensitive component, mainly active in web-copied code.

Backticks adjacent to nonbreaking-space indentation give large negative space
responses and positive backtick responses. The first code word after a backtick
also matters: types, declarations, literals and operators have different gains.
A few display-math boundaries are positive. Other contexts predict zero.
Gains approximate training averages; short history resets between documents.
"""
import keyword
import re

READS = ()
TYPES = set('''int long short float double char string String bool boolean
void List Dictionary struct enum typedef unsigned signed auto'''.split())
DECLARATIONS = set('''public private protected static const final class
using namespace def'''.split())
LITERALS = {'true', 'false', 'True', 'False', 'null', 'None', 'undefined'}
BUILTINS = {'range', 'print', 'printf', 'scanf', 'cout', 'cin', 'Console'}
KEYWORDS = set(keyword.kwlist) | {'switch', 'case', 'default', 'throw', 'new'}


def nbsp_run(s):
    return bool(s) and not s.lstrip(' ').strip('\xa0') and '\xa0' in s


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    tick = previous.endswith('`') and not previous.endswith('```')
    # Adjacent backtick spans or paired backticks, not triple-tick fences.
    web_code = '` `' in tail or bool(re.search(r'(?<!`)``(?!`)', tail))
    value = 0.0
    if nbsp_run(s):
        n = s.count('\xa0')
        if tick or (web_code and nbsp_run(previous)):
            if n == 1:
                value = -15.3
                if previous == '`':
                    value = -13.0
                elif previous == ' `':
                    value = -17.0
                if s.startswith(' '):
                    value = -10.5
            else:
                value = -1.0 - 8.0 / n**0.5
                if nbsp_run(previous):
                    value *= 0.7
            if not web_code:
                value *= 0.4
    elif s == '``' and nbsp_run(previous):
        value = 4.8
    elif s == '`' and nbsp_run(previous):
        value = 1.5
    elif s == ' `' and web_code:
        value = 3.0 if nbsp_run(previous) else (1.1 if tick else -0.35)
        if previous.endswith('=`'):
            value = 3.4
    elif tick:
        if s in LITERALS:
            value = -1.1
        elif s in DECLARATIONS:
            value = -5.7 if web_code else -0.9
        elif s in TYPES:
            value = -4.6 if web_code else -0.9
        elif s in KEYWORDS or s in BUILTINS:
            value = -3.5 if web_code else 0.0
        elif s == 'json':
            value = -1.5
        elif s in {'//', '#', '/*'}:
            value = -4.0 if web_code else -1.0
        elif web_code and s == '"':
            value = -10.0
        elif web_code and s.rstrip('`') in {'+', '-', '*', '/', '%', '='}:
            value = -3.8
        elif s in {';', '.', '\n\n', ' `(', ' `{'} and web_code:
            value = -2.0
        elif s.isdigit() and web_code:
            value = -3.8 if s == '1' else -1.2
    elif s in {'\n', '\n\n'} and previous.endswith('$$'):
        value = 1.2
    elif s == 'aligned' and tail.endswith('$$\\begin{'):
        value = 5.0
    elif s == 'split' and tail.endswith('$$\\begin{'):
        value = 2.5
    elif s == '\\"' and previous.endswith(('\\"', '\\t')):
        value = -0.7
    return (doc, s, (tail + s)[-96:]), value

"""Negative responses to HAVE-family forms and personal auxiliary contractions.

English HAVE is strongest directly after subjects, weaker after intervening
adverbs, modals, infinitival 'to', or another auxiliary. Pronouns and coarse
WordNet subject classes adjust its size. Related Germanic/Romance spellings
have larger negative responses; recent word frequencies help distinguish
these from English words and fragments. This is a lexical/grammatical
approximation, not a complete tense parser. All other tokens predict zero.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
WORDS = re.compile(r"[^\W\d_]+(?:['’][^\W\d_]+)?")
MODALS = set('can could may might must shall should will would'.split())
INTERVENERS = set('also already always never ever just still now often only '
                   'even probably certainly really actually previously recently '
                   'sometimes usually generally each both then moreover'.split())
AUXILIARIES = set('have has had having be been being am is are was were '
                  'do does did'.split())
GERMAN = set('habe hast hat haben habt hatte hatten hattet hätte hätten'.split())
FRENCH = set('a avons avez ont avait avais avaient avoir ayant '
             'aurait auraient avoit avoient'.split())
ITALIAN = set('ho ha abbiamo avete hanno aveva avevo avevano '
              'avrebbe avrebbero abbia abbiano'.split())
SPANISH = set('he has ha hemos habéis han había habían '
              'habrá habrán hubiera hubieran'.split())
NORDIC = set('har havde hadde ha'.split())
FRENCH_CUES = set('le la les du des de un une en au aux et ce ces dans '
                  'pour par sur avec pas ne qui que il elle ils elles on '
                  'nous vous est été son sa ses leur leurs se'.split())
SUBJECT_PRONOUNS = {
    'i': -4.05, 'he': -3.6, 'she': -3.6, 'who': -3.6,
    'we': -2.1, 'they': -2.55, 'you': -1.9, 'it': -2.05,
    'there': -4.3, 'that': -2.95, 'which': -2.0,
}


@lru_cache(maxsize=20000)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_margin(words, languages):
    """Recent words' average frequency advantage over English."""
    words = words[-9:]
    if not words:
        return -2.0
    return max(sum(frequency(w, lang) - frequency(w, 'en') for w in words)
               / len(words) for lang in languages)


@lru_cache(maxsize=10000)
def subject_adjustment(word):
    cats = wordnet.categories(word)
    return (-0.6 * ('noun.person' in cats) - 0.5 * ('noun.act' in cats)
            + 0.5 * ('noun.quantity' in cats) + 0.5 * ('noun.shape' in cats))


def english(word, previous, clause_words):
    prev = previous.lower()
    if prev.endswith(("'ll", '’ll')):
        return 0.1
    if prev in MODALS or prev == 'to':
        return 0.2 if prev in {'can', 'will', 'would', 'should'} else -0.25
    if prev in {'not', 'no'} or prev.endswith(("n't", 'n’t')):
        return 0.1
    if (prev in INTERVENERS or (prev.endswith('ly')
                               and 'adverb' in wordnet.parts_of_speech(prev))):
        return -0.05
    if prev in AUXILIARIES:
        return -0.55
    if word == 'having':
        return -1.7 if prev == 'after' else -0.35
    if word == 'have' and any(w.lower() in MODALS | {'do', 'does', 'did'}
                              for w in clause_words[-4:]):
        return 0.0
    if prev in SUBJECT_PRONOUNS:
        if previous in {'We', 'They', 'You'}:
            return {'We': -3.25, 'They': -3.65, 'You': -2.7}[previous]
        if prev == 'i' and word != 'have':
            return -3.55
        return SUBJECT_PRONOUNS[prev]
    return -2.0 + subject_adjustment(prev) - 0.45 * previous[:1].isupper()


def foreign(word, previous, words):
    if word in GERMAN:
        if word == 'hat' and language_margin(words, ('de',)) <= 0.15:
            return -0.6
        if word in {'haben', 'hatte', 'hatten'}:
            return -4.4
        return -2.8 if word in {'hätte', 'hätten'} else -5.0
    languages = tuple(lang for forms, lang in
                      [(FRENCH, 'fr'), (ITALIAN, 'it'), (SPANISH, 'es'),
                       (NORDIC, 'nb'), (NORDIC, 'sv'), (NORDIC, 'da')]
                      if word in forms)
    if not languages:
        return 0.0
    margin = language_margin(words, languages)
    if word == 'a':
        if (sum(w.lower() in FRENCH_CUES for w in words[-9:]) < 2
                or frequency(previous.lower(), 'en')
                > frequency(previous.lower(), 'fr') + 1.5
                or language_margin(words, ('es', 'it', 'pt')) > margin):
            return 0.0
    if margin <= 0.15:
        ambiguous = {'a', 'he', 'ho', 'han', 'har', 'ha', 'ont'}
        return 0.0 if word in ambiguous else -4.5
    if word == 'a':
        pronouns = {'il', 'elle', 'on', 'qui', 'ils', 'elles'}
        return -8.0 if previous.lower() in pronouns else -5.7
    if word in {'ont', 'avait', 'avaient'}:
        return -8.0
    if word == 'ha' and previous.lower() in {'se', 'gli', 'que', 'che'}:
        return -7.5
    if word in {'avoir', 'ayant', 'hadde', 'havde'}:
        return -3.6
    if word in {'avoit', 'avoient'}:
        return -5.7
    if word.startswith(('aur', 'avre')) or word in {'había', 'habían'}:
        return -4.7
    return -5.1 if word == 'har' else -6.4


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        text, previous_token = '', ''
    else:
        _, text, previous_token = carry
    word, words = token.strip().lower(), WORDS.findall(text)
    # Assemble an inflection split across tokens, including apostrophe elisions.
    if token[:1].isalpha() and text[-1:].isalpha() and words:
        word = words.pop().lower() + word
    elided = token[:1].isalpha() and text.endswith(("'", '’'))
    if elided and word in {'as', 'ai', 'a', 'est', 'ho'}:
        word = "'" + word
    tail = re.split("['’]", word)[-1]
    if tail in FRENCH | ITALIAN and tail != 'a':
        word = tail
    previous = words[-1] if words else previous_token.strip()
    prev = previous.lower()

    if word in {'have', 'has', 'had', 'having'}:
        clause_words = WORDS.findall(re.split(r'[.!?;\n]', text)[-1])
        value = english(word, previous, clause_words)
        if word != 'having':
            if any(c.isdigit() for c in previous_token):
                value = -0.9
            if len(previous) == 1 and prev != 'i':
                value = -0.5
            if ',' in previous_token:
                value = -2.6
        elif previous_token.strip() in {',', ';'}:
            value = -1.7
    elif word in {"'ve", '’ve'}:
        value = {'i': -6.5, 'you': -4.05}.get(prev, -5.0)
        if prev in MODALS:
            value = 0.0
    elif word in {"'d", '’d'}:
        value = {'i': -2.85, 'you': -0.7}.get(prev, -2.0)
    elif word in {"'s", '’s'}:
        value = {'he': -2.3, 'she': -2.3, 'that': -0.4,
                 'let': -0.3, 'who': -0.8}.get(prev, 0.0)
    elif word in {"'t", '’t'}:
        value = {'haven': -2.8, 'hasn': -2.1, 'hadn': -1.8}.get(prev, 0.0)
    elif word in {"'ai", '’ai'}:
        value = -7.8
    elif word in {"'a", '’a'}:
        value = -5.2 if any(w.lower() in FRENCH_CUES for w in words[-9:]) else 0.0
    elif word in {"'as", '’as'}:
        value = -4.8
    elif word in {"'est", '’est'} and prev == 's':
        value = -4.8
    else:
        value = foreign(word, previous, words)

    # Sentence-initial spellings often behave differently from medial verbs.
    if token.strip().lstrip("'’")[:1].isupper():
        if word in {'a', "'a", '’a', 'ha', 'ho', 'har', 'hat', 'he', 'han', 'ont'}:
            value = 0.0
        if word in {'have', 'had'}:
            value = -1.3
        if word == 'has':
            value = -1.8
    if (token == word and word in {'a', 'hat', 'ha', 'ho', 'har', 'han', 'he'}
            and not text[-1:].isspace() and not elided):
        value = 0.0
    return (doc, (text + token)[-180:], token), float(value)

programs.haiku:
"""Auxiliary "have" detector (negative): the component goes strongly negative on a
form of "have" used as a perfect-tense helper right after its subject, as in
"I've", "I have been", "they have made", "he has said", "il a", "se ha", "ho fatto".

It stays near zero when "have" follows a modal or infinitive marker ("will have",
"to have", "can have", "should have", "not have").

Magnitude follows the subject: "I've"/"’ve" is strongest (about -6), "I have" about
-5, "he/she/they/who/that/which + has/have" about -3.5, other subjects about -2.5.
Predicted value is 0 at every other token.
"""

READS = ()

# "have" forms in English and other languages
HAVE = {"have", "has", "had", "ha", "hat", "han", "hast", "hatte", "hadde", "hanno",
        "haben", "ho", "avez", "abbiamo", "avoir", "’ai"}
CONTRACTED = {"'ve", "’ve"}           # I've, we've, they've
FRENCH_SUBJECT = {"il", "elle", "y"}  # "il a", "elle a", "y a" (French "a" = has)
MODAL_OR_INFINITIVE = {"to", "will", "would", "can", "could", "should", "must",
                       "may", "might", "shall", "not", "also", "still", "probably"}
PRONOUN_SUBJECT = {"he", "she", "they", "who", "that", "which"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if len(prefix.token_strings) < 2:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    if before in MODAL_OR_INFINITIVE:
        return carry, 0.0
    if token in CONTRACTED:
        return carry, -6.0
    if token == "a" and before in FRENCH_SUBJECT:
        return carry, -4.0
    if token not in HAVE:
        return carry, 0.0
    if before == "i":
        return carry, -5.0
    if before in PRONOUN_SUBJECT:
        return carry, -3.5
    return carry, -2.5

programs.sol:
"""A sparse lexical-pattern approximation of this component.

The main response is negative on double underscores, especially a closing
__name__-style identifier. Additional rules recognize installation commands,
successful tests, installments, post-related phrases, Next.js and SQL TABLE
phrases. All other tokens receive zero. The rules use only the preceding
80 characters and reset at document boundaries; token boundaries matter.
