import re

READS = ()


def response(token, before):
    if token == '__':
        if not before:
            return -1.0
        if not (before[-1].isascii() and before[-1].isalnum()):
            return -0.35
        if re.search(r'(?<!\w)__[A-Za-z][A-Za-z_0-9]*$', before):
            return -5.0
        return -3.0
