    if token == '__/':
        return -1.25
    if token == '__.':
        return -0.72
    if token == '__(':
        return -0.43
    if token == '-get' and re.search(r'\bapt$', before):
        return 5.4
    if token == ' install':
        if re.search(r'\bapt(?:-get)?$', before):
            return 9.3
        if re.search(r'\byum$', before):
            return 8.3
        if re.search(r'\bpip[23]?$', before):
            return 5.2
        if re.search(r'\b(?:npm|gem|apm|setup\.py)$', before):
            return 3.2
    if token.lower() in ('ment', 'ments'):
        if re.search(r'\binstal[l]?$', before, re.I):
            return -7.0
    if token.lower() in (' pass', ' passed'):
        if re.search(r'\btests$', before, re.I):
            return 2.5
    if token == ' successfully':
        if re.search(r'\bran$', before):
            return 1.27
        if re.search(r'\bcreated$', before):
            return 0.82
    if token == ' from':
        if re.search(r'\bposts$', before, re.I):
            return -5.1
        if re.search(r'\bPosted$', before):
            return -2.6
    if token.lower() in (' office', ' offices'):
        if re.search(r'\bpost$', before, re.I):
            return -5.4
    if token.lower() == 'script' and re.search(r'\bpost$', before, re.I):
        return -5.0
    if token in ('.js', 'js') and re.search(r'next$', before, re.I):
        return -3.5
    if token.lower() == ' table':
        if re.search(r'\balter$', before, re.I):
            return -2.8
        if re.search(r'\bcreate(?:\s+temporary)?$', before, re.I):
            return -1.5
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (document, (before + token)[-80:]), value

