import unicodedata

READS = ()
ARABIC = regex.compile(r'^[\p{Script=Arabic}\p{M}]+$')
PERSIAN_MARKERS = frozenset('گچپژکی')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
