    elif word == 'هذه':
        value = -4.4
    elif word in {'ذلك', 'وهذا'}:
        value = -3.5
    elif word == 'إذ':
        value = -3.7
    elif word == 'إذا':
        value = -1.8
    elif word in {'التي', 'الذي', 'الذين'}:
