        if prefix.text_prefixes[-2].endswith(('θ', 'Θ')):
            value = -2.2 if word.startswith(('α', 'ε')) else -0.8
    return (doc, token, previous, age, strength, persian), value

"""A lexical opening-of-context signal, not a general number detector.

At the first token of a row or document, predict positive values for numeric
characters, small-number words, ordinals, and singular/selecting determiners.
Predict negative values for most other words, especially auxiliaries and negation.
Code openings, whitespace, punctuation, and scripts refine these baselines.
Later tokens get zero.
These broad classes deliberately omit individual word-specific variation.
"""
import unicodedata
import inflect

READS = ()
_engine = inflect.engine()
CARDINALS = frozenset(_engine.number_to_words(i) for i in range(1, 10))
ORDINALS = frozenset(_engine.ordinal(w) for w in CARDINALS)
AUXILIARIES_OR_NEGATION = frozenset(
    'am is are was were be been being have has had can could will would '
    'shall should may might must not'.split()
)
PRONOUNS_AND_POSSESSIVES = frozenset(
    'we he she it they me us him her them my our your his its their'.split()
)


def opening_value(text):
    word = text.strip()
    lower = word.lower()
    spaced = text.startswith(' ')
    if text.startswith('<|'):
        return -3.1
    number = (int(word) if word.isdecimal() else
              unicodedata.numeric(word, None) if len(word) == 1 else None)
    if number is not None:
        return 10.0 + 0.5 * min(number, 8)
    if not word:
        if text == '\n':
            return 2.6
        if text == '\n\n':
            return -1.5
        if '\n' in text or '\r' in text:
            return 1.2
        if text == '\t':
            return 4.2
        return 5.2 if len(text) <= 2 else 1.5
    if lower == 'one':
        return (26.0 if word.istitle() else 21.0) - 9.0 * spaced
    if lower in ORDINALS or lower in {'next', 'last'}:
        return 8.0
    if lower in {'each', 'every', 'another', 'single', 'which'}:
        return 10.0
    if lower in CARDINALS:
        return 4.0 if spaced else 8.0
    if lower == 'a':
        return 3.5 if spaced else 11.5
    if lower == 'an':
        return -4.0 if spaced else -0.5
    if lower == 'this':
        return 2.3
    if lower in {'multi', 'multiple'}:
        return 5.0
    if lower in AUXILIARIES_OR_NEGATION:
        return -7.0
    if lower == 'to':
        return -8.3
    if lower == 'with':
        return -6.5
    if lower == 'the':
        return -3.0 if text == 'The' else -5.0
    if lower in PRONOUNS_AND_POSSESSIVES:
        return -5.4
    if lower == 'you':
        return -2.0 if word.istitle() else -4.8
    if lower == 'i':
        return -3.5 if spaced else -1.0
    if text in {'class', 'package'}:
        return 8.0
    if word.startswith(('<?', '#!')):
        return -8.0
    directive = word.startswith('#') and len(word) > 1 and word[1].isalpha()
    if lower in {'import', 'using'} or directive:
        return -6.5
    if word in {'.', '。'} and text.endswith('\n') and text.count('\n') == 1:
        return 6.5
    if word in {',', ')', ']', '}'}:
        return 1.0
    if word in {'(', '[', '{', '=', '-'}:
        return -2.0
    if len(word) == 1 and word.isascii() and word.isalpha():
        return 0.0
    if any('LATIN' in unicodedata.name(c, '') for c in word):
        return -3.0
    if any('CYRILLIC' in unicodedata.name(c, '') for c in word):
        return -3.6
    if any('ARABIC' in unicodedata.name(c, '') or
           'HANGUL' in unicodedata.name(c, '') for c in word):
        return -2.8
    return -0.3


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, opening_value(prefix.token_strings[-1]) if first else 0.0

programs.haiku:
"""Layer-1 MLP down-projection, component 1749: a document-start detector.

What it does, in plain terms. Its value (the component's contribution to the residual
stream at that token) is set almost entirely by the first token of a document, or of a
packed row, where attention has nothing earlier to look at:
- digits (0-9, also fullwidth): about +11;
- number words, ordinals and 'a', 'one', 'each', 'every' ('One', 'First', 'a'): about +8;
- whitespace or newline only: about +3;
- punctuation and symbols: about 0;
- quantifiers such as 'all', 'some', 'many', 'any', 'both': about 0;
- other words: about -2.5;
- determiners, prepositions, pronouns and conjunctions ('the', 'of', 'to', 'with', 'it'):
  about -4;
- auxiliary and modal verbs ('is', 'was', 'can', 'will', 'have'): about -7.
Separately, the two-character token '··' (two middle dots) gives a fixed +7.8 wherever it
occurs. Every other token gives 0.
"""
import unicodedata

READS = ()
DOT_PAIR = "··"
NUMBER_WORDS = set(
    "one two three four five six seven eight nine ten eleven twelve twenty hundred thousand "
    "first second third fourth fifth sixth last next each every another a".split()
)
QUANTIFIERS = set("all some any many most both several various other multiple an".split())
AUX_WORDS = set(
    "is are was were be been being have has had do does did can could will would shall "
    "should may might must".split()
)
FUNCTION_WORDS = set(
    "the this that these those its their his her my your our I you he she it we they me him "
    "us them of to in on at by for with from into about as than between through during after "
    "before under over and or but so because if when while which who where what how".split()
)


def start_value(s):
    word = s.strip()
    if word == "":
        return 3.0
    if unicodedata.category(word[0]) == "Nd":
        return 11.0
    if word.lower() in NUMBER_WORDS:
        return 8.0
    if not any(ch.isalnum() for ch in word):
        return 0.0
    if word.lower() in QUANTIFIERS:
        return 0.0
    if word.lower() in AUX_WORDS:
        return -7.0
    if word.lower() in FUNCTION_WORDS:
        return -4.0
    return -2.5


def step(carry, prefix, upstream):
    t = prefix.position
    s = prefix.token_strings[t]
    starts = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if s == DOT_PAIR:
        return None, 7.8
    if starts:
        return None, start_value(s)
    return None, 0.0

