"""Approximate a sparse document-onset signal, especially code declarations.

The largest positive pulses mark an opening class/function declaration or
NUL-prefixed text. Capitalized words get a weaker onset pulse. The numeric
prefix '12' instead gives a negative pulse on its second digit. Small
punctuation responses approximate the component away from document starts.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening = 0, s
    else:
        _, previous_position, opening = carry
        position = previous_position + 1

    value = 0.0
    if s == '\x00':
        value = 0.12
    elif s.strip() == '://':
        value = 0.10
    elif s.strip() in {'=>', '->'}:
        value = 0.06
    elif s.strip() == '=':
        value = -0.047
    elif s.strip() in {'[', ']'}:
        value = -0.045
    elif s.strip() in {'–', '—'}:
        value = -0.065
    elif s.strip() in {'“', '”'}:
        value = 0.055

    if position == 0:
        value = 0.0
        if s == '\x00':
            value = 2.13
        elif s == '<|endoftext|>':
            value = 1.30
        elif s in {'class', 'function', '(function', 'func', 'object', 'pub'}:
            value = 1.58
        elif s in {'module', 'type'}:
            value = 1.20
        elif s in {'def', 'namespace', 'var', 'int', 'char'}:
            value = 0.80
        elif s in {' class', ' function'}:
            value = 0.72
        elif s == ' .':
            value = -1.17
        elif s == '\t':
            value = -0.60
        elif s.isascii() and s.isalpha() and s.istitle():
            value = 0.25
    elif position == 1 and opening == '1' and s == '2':
        value = -1.46

    return (doc, position, opening), value

"""Recognize detached Romance word endings, not arbitrary token identities.

Negative responses are strongest for particular stem--suffix spellings:
-dura/-sura, -iture, -eur and the curv- family. Short stems are ignored.
Separate rules cover tokens containing 則/则, 一方面/另一方面,
the Chinese degree suffix 度, French-context 'lecture', and repeated middle dots. These rules approximate
training averages and leave unrecognized tokens at zero.
"""
import regex
READS = ()
LATIN_END = regex.compile(r"[\p{Latin}\p{M}]+$")
HAN_END = regex.compile(r"\p{Script=Han}$")
MEASURE_PROPERTIES = set("酸稠粘密浓濃硬软溫温湿濕強强弱速广廣长長高低厚薄深浅淺亮暗")
FRENCH_BEFORE_NOUN = set("de du la une sa des leur cette en".split())


def romance_ending(stem, token):
    if len(stem) < 3:
        return 0.0
    stem = stem.lower()
    last = stem[-1]
    if token in ('ura', 'uras', 'atura'):
        if stem.endswith('curv'):
            return -4.5
        if token == 'atura':
            return -2.8
        if token == 'uras':
            return -0.55
        if last in 'dsg':
            return -4.0
        return -0.85 if last == 't' else 0.0
    if token in ('ure', 'ures', 'oure'):
        if stem.endswith(('rit', 'clot', 'cout')):
            return -4.5
        return -0.8 if token == 'oure' else -0.12
    if token in ('ur', 'urs', 'eur', 'eurs'):
        if token in ('eur', 'eurs'):
            return -0.6
        if last == 'e':
            return -1.0
        if last == 'r':
            return -0.8
        return -0.6 if last == 't' else 0.0
    if token in ('age', 'ages', 'agem', 'agens', 'aje', 'rage', 'mage'):
        if last in 'gdmlfvç' or token in ('rage', 'mage'):
            return -1.7
        return 0.0 if last == 'h' else -0.65
    if token in ('ature', 'atures', 'atur', 'ture'):
        return -4.5 if stem.endswith('curv') else -1.0
    if token in ('amento', 'amiento', 'amentos', 'amientos', 'amenti'):
        return -1.15
    if token in ('imento', 'imiento', 'imentos', 'imientos', 'imenti'):
        return -0.6
    if token in ('ento', 'iento', 'entos', 'ientos'):
        return -1.8 if last == 'm' else 0.0
    if token in ('ement', 'ements', 'lement', 'issement'):
        return -0.35
    if token in ('ador', 'adores', 'adora', 'adoras', 'ateur', 'ateurs', 'isor'):
        return -0.5
    if token == 'zza' and last == 'e':
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        _, stem, previous_bytes = carry
    else:
        stem, previous_bytes = '', b''
    token = prefix.token_strings[-1]
    match = LATIN_END.search(token)
    tail = match.group() if match else ''
    word = ((stem + tail) if tail == token else tail)[-80:]
    previous = previous_bytes.decode('utf-8', errors='ignore')
    byte_tail = (previous_bytes + prefix.token_bytes[-1])[-12:]
    carry = (doc, word, byte_tail)
    if token == '一方面':
        return carry, 3.0
    if token == '另一方面':
        return carry, 0.8
    if token in ('则', '則'):
        return carry, 4.2
    if token.startswith(('则', '則')):
        return carry, 2.5
    if '则' in token or '則' in token:
        return carry, 1.0
    if token == '度' and HAN_END.search(previous):
        value = -1.3 if previous[-1] in MEASURE_PROPERTIES else -0.4
    elif token == ' lecture' and stem.lower() in FRENCH_BEFORE_NOUN:
        value = -3.5
    elif token in (' curvature', ' curvatures'):
        value = -2.0
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -0.7
    else:
        value = romance_ending(stem, token.lower())
    return carry, value

"""Sparse email/forum-formatting cues, with a separate positive test-log cue.

Predict negative values at reply attributions, forwarded-message headers,
quoted replies, address endings, abbreviated dates and discussion metadata.
Remember mail formatting until the document ends, so email quote markers
receive a stronger response than ordinary Markdown or code. Leave other
activations near zero; this is a partial approximation, not a topic classifier.
"""
import re
import regex

READS = ()
DAYS = dict(Mon=-1.0, Tue=-2.6, Wed=-1.2, Thu=-5.0,
            Fri=-2.8, Sat=-0.6, Sun=-0.4)
DATE_DAYS = dict(Mon=-5.0, Tue=-5.2, Wed=-8.0, Thu=-10.0,
                 Fri=-5.0, Sat=-3.0, Sun=-2.0)
FIELDS = dict(From=-3.0, To=-2.7, Sent=-6.0, Subject=-6.0, Date=-3.3)
COLONS = dict(From=-4.8, To=-5.5, Sent=-2.5, Date=-2.5)
# Familiar labels in mail archives and discussion pages.
PHRASES = {'mailing list': -7.5, 'Original Message': -5.0,
           'Author Message': -7.0, 'Started by': -7.0,
           'Next message': -9.0, 'Previous message': -9.0,
           'Behalf Of': -8.5, 'Archive Date': -6.2}


def predict(token, history, mail):
    s = token.strip()
    line = history.rsplit('\n', 1)[-1].strip().lstrip('> ').strip()
    words = history.rstrip().split()
    last = words[-1] if words else ''
    phrase = last + ' ' + s
    if phrase in PHRASES:
        return PHRASES[phrase]
    if s in DAYS:
        if line == 'On':
            return -10.5
        return (DATE_DAYS if mail or last.lower() == 'on'
                or line.endswith('Date:') else DAYS)[s]
    if s == ',' and last in DAYS:
        return -12.0 if line.startswith('On ') else -2.5
    if s == 'wrote':
        if history.rstrip().endswith('>'):
            return -7.5
        metadata = re.search(r'\d{1,2}:\d\d|#permalink|wrote:', history)
        if len(line.split()) <= 3 and '\n' in history:
            return -5.2 if metadata and not regex.search(r'\p{Han}', history) else -1.4
        return 0.2
    if s == ':':
        if last == 'wrote':
            if '\n' not in token or 'user' in line.lower():
                return -3.0
            return -5.0 if regex.search(r'\p{Han}', history[-70:]) else -8.0
        if last == 'Re':
            return -4.5 if mail else -2.2
        if last in COLONS and line == last:
            return COLONS[last]
        if last == 'news' and 'message' in history:
            return -9.0
    if s.startswith('>') and (len(s) == 1 or s[1].isalpha()):
        if not line or last == '>':
            return (-4.0 if '\n' in token else -5.5) if mail else -1.0
        return -0.08
    if s in FIELDS and mail and not line:
        return FIELDS[s]
    if s == 'Original' and history.rstrip().endswith('-----'):
        return -7.5
    if s == 'mailto' and 'From:' in history and line.endswith('['):
        return -11.0
    if s == 'On' and mail and line.endswith(']'):
        return -8.0
    if s in ('.org', '.com', '.net', '.edu', '.groups'):
        if re.search(r'@[\w.-]*$', history):
            if s == '.org':
                return (-7.5 if history.endswith('@example') and len(history) > 12
                        else -2.2)
            return {'.com': -1.6, '.groups': -3.5}.get(s, -0.2)
        return -0.3 if s == '.org' else 0.0
    if s == '-ID' and last == 'Message':
        return -11.0
    if s == 'message' and history.rstrip().endswith('wrote in'):
        return -10.0
    if s == 'unsubscribe' and 'mailing list' in history:
        return -7.5
    if s == '?' and line.endswith('[') and 'kudos' in line.lower():
        return -2.3
    if s == 'PASS' and line == '---':
        return 0.5
    return 0.001


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    history, mail = ('', False) if carry is None or carry[0] != document else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, history, mail)
    line = history.rsplit('\n', 1)[-1].strip().lstrip('> ').strip()
    if token.startswith(':') and (line in ('From', 'Re')
            or line.endswith(' wrote') and 'user' not in line.lower()):
        mail = True
    if token.strip() == 'Original' and history.rstrip().endswith('-----'):
        mail = True
    if 'wrote in message news:' in history + token:
        mail = True
    history = (history + token)[-240:]
    if token == '<|endoftext|>':
        history, mail = '', False
    return (document, history, mail), float(value)

"""Indonesian-context word pieces.

Accumulate fading language evidence from completed words: Indonesian function
words and words more frequent in Indonesian than in several other languages.
In that context, short Latin word fragments get the largest predictions;
very common Indonesian pieces and longer fragments get smaller ones.
The small frequency/length rule tree is calibrated on training activations.
This is an approximation, especially for isolated names without language cues.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

FUNCTION_WORDS = frozenset('''
yang untuk dari dengan tidak adalah akan pada mereka juga atau dalam oleh
sebagai sudah lebih bisa karena sangat hanya sebuah telah tersebut setiap
namun serta bahwa kepada tentang saja masih antara bukan menjadi jika agar
ketika siapa bagaimana tanpa sampai setelah sebelum semua dapat kamu
'''.split())


@lru_cache(maxsize=200000)
def frequency(word, language):
    return zipf_frequency(word, language) if word else 0.0


@lru_cache(maxsize=100000)
def language_evidence(word):
    """Evidence from common words distinctive to Indonesian, not shared loans."""
    indonesian = frequency(word, 'id')
    if indonesian < 4.3 or len(word) < 2:
        return 0.0
    others = max(frequency(word, language) for language in
                 ('en', 'de', 'es', 'fr', 'it', 'pt', 'nl', 'tr', 'vi'))
    return max(0.0, min(1.0, (indonesian - others - 0.3) / 1.7))


def predict(context, word, piece, alphabetic):
    indonesian = frequency(word, 'id')
    english = frequency(word, 'en')
    difference = indonesian - english
    if context <= 1.5:
        return 0.81578 if difference > 3.875 else 0.00126

    if english <= 2.125:
        if not alphabetic:
            return 0.12235
        if difference > 4.375:
            return 0.81382
        return 2.45787 if len(word) <= 5 else 1.50421

    piece_frequency = frequency(piece, 'id')
    if piece_frequency >= 6.0:
        return -0.27009 if piece_frequency > 7.375 else 1.19777
    if len(word) > 4:
        return 1.13747
    if english > 6.875:
        return 0.94355
    return 3.57431 if len(word) <= 3 else 2.53326


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0.0)
    _, word, context = carry
    context *= 0.92
    text = prefix.token_strings[-1]
    # A boundary completes the old word; letters extend the current fragment.
    for part in re.findall('[A-Za-z]+|[^A-Za-z]+', text):
        if part[0].isascii() and part[0].isalpha():
            word += part.lower()
        else:
            if word:
                context += language_evidence(word)
                if word in FUNCTION_WORDS:
                    context += 0.5
            word = ''
    piece = ''.join(ch for ch in text if ch.isascii() and ch.isalpha()).lower()
    alphabetic = bool(piece) and text.strip().isascii() and text.strip().isalpha()
    return (document, word, context), predict(context, word, piece, alphabetic)

"""A local spelling contrast around j: consonant+j is usually positive,
vowel+j negative. Keep a short, fading signal in following word fragments.
Letter classes, token length, case, and a few neighbouring vowels adjust it.
Also recognize Serbian љ/њ and Cyrillic soft-sign + iotated vowels.
These are approximate class averages, not word or token-ID lookups.
"""
import math
import unicodedata

READS = ()

# At j / in a following fragment, classified by the letter BEFORE j.
SCORES = {
    'edge': (0.08, -0.15),
    'eiy': (-0.20, -0.05),
    'ao': (-0.58, -0.36),
    'u': (-1.36, -0.53),
    'accented': (-1.37, -0.23),
    'l': (3.60, 1.11),
    'r': (2.14, -0.20),
    't': (3.73, 2.94),
    'n': (1.99, 0.49),
    's': (1.79, 0.66),
    'bfghk': (1.60, 1.77),
    'consonant': (0.63, 0.33),
}
VOWELS = {'eiy', 'ao', 'u', 'accented'}
AFTER_J = dict(zip('aeiou', (0.18, 0.16, -0.64, 0.01, -0.70)))
FRAGMENT_START = {'eiy': 0.10, 'ao': 0.15, 'u': -0.63,
                  'accented': -0.52, 'l': 0.56}


def base(ch):
    return unicodedata.normalize('NFD', ch.lower())


def letter_class(ch):
    letters = base(ch)
    if not letters or not letters[0].isalpha():
        return 'edge'
    if letters[0] in 'aeiouy':
        if len(letters) > 1:
            return 'accented'
        return 'eiy' if letters[0] in 'eiy' else 'u' if letters[0] == 'u' else 'ao'
    for name, chars in (('l', 'lл'), ('r', 'rр'), ('t', 'tт'),
                        ('n', 'nн'), ('s', 'sс'), ('bfghk', 'bfghk')):
        if letters[0] in chars:
            return name
    return 'consonant'


def nearest_j(text, start, token):
    for i in range(len(text) - 1, -1, -1):
        ch = text[i]
        if ch in 'jJ':
            before = text[i-1] if i else ''
        elif ch in 'љЉњЊ':
            before = 'l' if ch in 'љЉ' else 'n'
        elif ch.lower() in 'яюёеє' and i >= 2 and text[i-1].lower() == 'ь':
            before = text[i-2]
        else:
            continue
        if i < start:
            between = text[i+1:start]
            if len(between) > 2 or not all(c.isalpha() for c in between):
                continue
            if not token or not token[0].isalpha():
                continue
        return i, ch, before
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text, start = tail + token, len(tail)
    found = nearest_j(text, start, token)
    value = 0.0
    if found is not None:
        i, ch, before = found
        current = i >= start
        group = letter_class(before)
        consonant = group not in VOWELS and group != 'edge'
        scores = SCORES[group]
        if ch not in 'jJ':
            scores = ((2.21, 0.43) if group in ('l', 'r') else
                      (2.42, 0.02) if group == 'n' else (0.91, 0.15))
        value = scores[0 if current else 1]
        after = text[i+1:i+2].lower()
        first = letter_class(token[0]) if token else 'edge'
        if current:
            value += AFTER_J.get(after, 0.0)
        else:
            value += FRAGMENT_START.get(first, 0.0)
        if consonant and ch in 'jJ':
            earlier = text[i-2] if i >= 2 else ''
            if letter_class(earlier) not in VOWELS | {'edge'}:
                value += 0.38 if current else 0.14
            if base(earlier).startswith('i'):
                value += 1.57 if current else 0.15
            if not current and first == 'accented':
                value += 2.14
            if current and after.isalpha() and after not in 'aeiouy':
                value -= 1.0
        distance = max(0, start - i - 1)
        length_decay = 3.0 if current else 0.3
        value *= math.exp(-length_decay * max(0, len(token.strip()) - 3)
                          - 0.8 * distance)
        if ch.isupper():
            value *= 0.2
        if current and i > start:
            value *= 0.7
    return (doc, (tail + token)[-5:]), float(value)

"""Lexical body/form syllables, a start-of-document offset, and 'Title:'.

The main positive family is the character 体/體 and short compounds containing
it. It is not an anatomy detector: some biological compounds barely respond.
Korean 체, Vietnamese thể and Russian тел have related responses, including
homophones. Compound spelling and a few immediately preceding syllables set
the gain. A colon after document-initial 'Title' has a separate large spike.
Split body/hair bytes are recognized too. Double middle dots get a negative
response; otherwise the default is zero, or a small negative initial-token bias.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, previous, tail, raw = 0, '', '', b''
    else:
        _, n, previous, tail, raw = carry
    token = prefix.token_strings[-1]
    newest = prefix.token_bytes[-1]
    word = token.strip()
    value = 0.0

    if word in ('体', '體'):
        value = 5.3 if word == '体' else 5.9
        # Bound compounds: main unit, conductor, window, memory, itself.
        if tail.endswith(('本', '导', '導', '窗', '记忆', '記憶')):
            value = 2.0
        elif tail.endswith(('自', '団', '团', '単', '单', '晶', '玻璃')):
            value = 3.8
        elif tail.endswith(('身', '肉', '肢', '尸', '屍')):
            value = 0.3
    elif word == '休':  # Visual neighbour of 体: a person beside a tree.
        value = 4.5
    elif '体' in word or '體' in word:
        if word in ('身体', '身體'):
            value = 4.1 if tail.endswith(('亲', '親', '切')) else 0.2
        elif len(word) == 2 and word[-1] in '体體':
            if word[0] in '全总總一':  # Totality / unity.
                value = 5.6
            elif word[0] in '身肉尸屍肢抗':  # Biological compounds.
                value = 0.2
            elif word[0] in '软軟硬导導':  # Software / hardware / conductors.
                value = 0.1
            elif word[0] == '媒':
                value = 0.7
            elif word[0] in '人个個整物':
                value = 3.7
            else:
                value = 2.5
        elif len(word) == 2:
            value = 1.3
            if word[-1] in '验驗育力':
                value = 0.6
            elif word[-1] in '系重温溫检檢彩':
                value = 0.0
        elif len(word) == 3:
            value = 1.0
    elif word in ('체', '전체'):
        value = 5.2 if word == '체' else 3.7
    elif word == 'thể':
        last = tail.split()[-1].lower() if tail.split() else ''
        value = 6.0
        if last in ('có', 'cơ', 'cụ'):
            value = 1.8
        elif last in ('không', 'chẳng', 'toàn', 'chủ'):
            value = 3.5
    elif re.search(r'(?<![а-яА-Я])[тТ]$', tail):
        if word == 'ел':
            value = 4.0
        elif word in ('ела', 'ело'):
            value = 2.4
    elif word == 'ัว' and tail.endswith('ต'):  # Thai ตัว, body / self.
        value = 2.3
    elif word == '··':
        value = -0.95

    # A split UTF-8 character can finish the same Korean body syllable.
    if newest == b'\xb4' and raw.endswith(b'\xec\xb2'):
        value = 9.2
    elif newest == b'\xe9\xab':  # Bone/hair characters' shared byte prefix.
        value = 0.8

    if n == 0 and value == 0.0 and not token.startswith('<|'):
        value = -0.35
        if word.isascii():
            if word.isalpha():
                value = -0.45 if word[0].isupper() else -0.35
            else:
                value = -0.2
    if n == 0 and word == 'Title':
        value = -1.4
    elif n == 1 and previous == 'Title' and token == ':':
        value = 11.0

    state = (doc, n + 1, token, (tail + token)[-80:], (raw + newest)[-4:])
    return state, value

"""Markup and typesetting boundaries, rather than ordinary prose.

Recognize separately tokenized HTML/BBCode tag names, numeric bracket closings,
TeX font commands, documentation directives, and formula-like subscripts.
Quote escapes and patent-reference spacing have smaller signed responses.
Pure runs of line-extension/control characters get their own response.
Initializer-name prefixes in paths are another delimited-name case.
These rules approximate training peaks, not ordinary lexical variation.
Ordinary text is left at zero. A short document-local suffix supplies context.
"""
import re

READS = ()

# Common formatting elements: their name tokens have different strengths.
TAGS = {
    'b': 4.2, 'i': 1.5, 'u': 1.3, 's': 0.6,
    'strong': 3.0, 'em': 4.9, 'font': 3.0,
    'small': 3.1, 'abbr': 2.8, 'a': 1.3, 'br': 1.2,
    'hr': 0.9, 'span': 1.0, 'div': 0.4, 'p': 0.75,
    'code': 4.8, 'pre': 2.2, 'td': 1.1, 'th': 1.1,
    'li': 0.75, 'ul': 1.0, 'img': 0.6, 'center': 2.9,
}
BBCODE = {
    'b': 1.2, 'i': 0.2, 'u': 0.2, 'br': 1.5,
    'quote': 2.4, 'url': 3.2, 'email': 2.6, 'tex': 4.2,
    'IMG': 5.5, 'COLOR': 6.4, 'bold': 2.8, 'center': 2.7,
}
COLORS = set('black white red green blue yellow cyan magenta gray grey'.split())
LABELS = {
    'INFO': 1.8, 'Edit': 1.2, 'edit': 3.0, '编辑': 3.0,
    '編': 1.4, 'emphasis': 1.8, 'Source': 0.6,
}
FILLER_RUNS = {'⎯': 2.93, '\r': 2.2, '\x00': 3.2}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.lower()
    value = 0.0
    marker = re.search(r'(\[/?|</?)$', tail)
    if marker and token == token.strip():
        closing = marker[0].endswith('/')
        if '[' in marker[0]:
            value = BBCODE.get(token, LABELS.get(token, 0.0))
            if closing and token == 'b':
                value = 4.6
            if word in COLORS and not re.search(r'\\[a-zA-Z]+\[$', tail):
                value = 4.0 if closing else 2.6

        else:
            value = TAGS.get(word, 0.0)
            if closing:
                value *= 0.3 if word in ('div', 'li', 'ul', 'th', 'pre') else 0.8
                if word in ('p', 'head'):
                    value = -0.72 if word == 'p' else -1.36
            if token in ('module', 'class'):
                value = 2.2
            if token in ('function', 'init', 'see'):
                value = 4.3
            if token == 'string':
                value = 1.4
            if word in ('author', 'annotation'):
                value = 2.5 if closing else 3.5
    if marker and token in ('http', 'https'):
        value = 2.5
    if token == 'code' and tail.endswith('{@'):
        value = 4.0  # Java's inline-code documentation tag
    if token == ' code' and tail.endswith('..'):
        value = 3.0  # reStructuredText code directive
    if token in ('<p', '<br'):
        value = 0.6 if token == '<p' else 1.4
    if token == 'ex' and tail.endswith('[t'):
        value = 6.5  # opening [tex], split into two tokens
    if token == ']':
        m = re.search(r'\[([0-9]+)$', tail)
        if m:
            spaced = len(tail) > len(m[0]) and tail[-len(m[0])-1].isspace()
            value = (0.4 if len(m[1]) == 1 else 0.67) if spaced else (
                0.0 if len(m[1]) == 1 else 0.4)
    if token in ('.sub', '.sup'):
        if re.search(r'(?<![A-Za-z_])(?:[A-Z][a-z]?\d*)+$', tail):
            value = 4.0  # formula-like patent subscripts/superscripts
        elif re.search(r'(?<![A-Za-z_])[a-z]$', tail):
            value = 3.0
    if tail.endswith('\\') and token in ('it', 'tt', 'code'):
        value = 1.3
    if tail.endswith('\\math') and token == 'it':
        value = 2.2
    if tail.endswith('/__') and token == 'init':
        value = 2.8  # Python initializer-name prefix in a path
    if token in FILLER_RUNS:
        value = FILLER_RUNS[token] if not tail.strip(token) else 0.15
    if token.endswith('[@'):
        value = -0.75
    if token == '\\xe' or (tail.endswith('\\') and token == 'xe'):
        value = -1.7 if token.startswith('\\') else -1.4
    elif tail.endswith('\\') and token == 'xc':
        value = -0.5
    elif token == '\\x':
        value = -0.16
    if token.strip() == '&#':
        value = -0.5
    if tail.endswith('&#') and token == '3':
        value = -0.35
    if tail.endswith('&#3') and token in ('4', '9'):
        value = 0.6
    if token in ('  ', '   '):
        if re.search(r'  +[0-9]+$', tail) or re.search(r'\[\d{4}\]$', tail):
            value = -0.32
    return (doc, (tail + token)[-96:]), value

programs.haiku:
"""Layer-1 MLP down-projection feature 1759: a markup-tag-name detector.

It fires on the name of an HTML tag written right after an opening "<" or closing "</"
(the "em" in "<em>", the "sub" in "</sub>"). It is strongest for inline text-formatting
tags (em, b, tt, sub, code, strong, i, small, font, big, ul) and weak for layout tags
(span, td, a, br, pre), and it is silent for block tags such as div, p, li and tr. It also
fires on LaTeX/chemistry subscript and superscript tokens (CH.sub.3, R.sup.2), on "init"
in "__init__", and goes negative on escaped hex-byte text such as "\\xe2".
"""

READS = ()

# activation when the tag name follows "<" or "</"
INLINE_TAG_ACTIVATION = {
    "sub": 7.0, "tt": 6.0, "em": 5.5, "b": 5.0, "code": 4.5, "CODE": 3.7, "strong": 3.5,
    "i": 3.5, "font": 3.0, "FONT": 4.2, "small": 3.4, "big": 2.0, "ul": 2.5, "module": 2.3,
    "span": 1.2, "td": 1.2, "br": 1.1, "BR": 3.1, "pre": 1.2, "a": 1.0,
    "function": 4.5, "green": 4.2, "blue": 3.0, "red": 2.6, "center": 2.9, "http": 2.6,
}
SCRIPT_TOKEN_ACTIVATION = {".sub": 1.0, ".sup": 3.0}
ESCAPED_BYTE_TOKENS = {"\\xe", "xe", "\\xc", "\\xa"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur in SCRIPT_TOKEN_ACTIVATION:
        return carry, SCRIPT_TOKEN_ACTIVATION[cur]
    if cur in ESCAPED_BYTE_TOKENS:
        return carry, -1.5
    if cur == "init" and prev == "__":
        return carry, 2.5
    if prev.endswith("<") or prev.endswith("</"):
        return carry, INLINE_TAG_ACTIVATION.get(cur, 0.0)
    return carry, 0.0

programs.sol:
"""Approximate the component's local English noun-phrase signal.
Existence and possession contexts raise a determiner's activation, especially
"this". Some extent, negation and directional phrases instead get negative
values. This only models these English patterns, not every component response.
A three-token history is cleared at document boundaries.
"""
from functools import lru_cache
import wordnet

READS = ()
# Each determiner has an offset and a gain on the preceding context signal.
DETERMINERS = {
    'a': (-0.043, 1.000),
    'an': (-0.029, 1.119),
    'another': (-0.020, 1.080),
    'one': (0.171, 1.623),
    'these': (0.040, 0.771),
    'this': (-0.003, 4.522),
}
BE = set("is are was were be been being".split()) | {"'s", "’s"}
HAVE = set("have has had having got".split())
MODAL = set("to can could will would may might must should".split())
PERSONAL = set("i you we he she they it".split())
PREPOSITIONS = set(
    "in on at of to for from as by about like into over through".split()
)
ADVERBS = set("also still only just even always already".split())
@lru_cache(maxsize=30000)
def parts(word):
    return wordnet.parts_of_speech(word) if word.isalpha() else ()

@lru_cache(maxsize=30000)
def past_form(word):
    return word.endswith('ed') or (
        not word.endswith(('s', 'ing'))
        and bool(set(wordnet.base_forms(word)) - {word})
    )


def context_strength(p, q, r):
    strength = 0.0
    if p in HAVE:
        strength += 0.591
        if p == 'having': strength -= 0.248
        if p == 'had': strength += 0.143
        if q in MODAL: strength -= 0.255
        if q in PERSONAL: strength += 0.362
    elif p in BE:
        strength += 0.108
    elif p not in PREPOSITIONS | DETERMINERS.keys() | {'that', 'all', 'no'}:
        if 'verb' in parts(p):
            strength += 0.070
            if past_form(p): strength += 0.124
            if p in {'exist', 'exists', 'existed', 'arose', 'arises'}:
                strength += 0.715
            if p in {
                'found', 'saw', 'heard', 'discovered', 'noticed', 'observed'
            }:
                strength += 0.458
    if p in {"'s", '’s'}: strength += 0.155
    if p in {'with', 'without'}: strength += 0.106
    if p in PREPOSITIONS: strength += 0.026
    existential = (
        (p in BE and (q == 'there' or r == 'there'))
        or (p in ADVERBS and q in BE and r == 'there')
    )
    if existential:
        strength += 1.465
        if p in BE and q == 'there':
            if r in {
                'if', 'whether', 'when', 'unless', 'since', 'that', 'because', 'as'
            }:
                strength -= 0.358
            if r in {'', '.', ',', ';', ':', '!', '?'}:
                strength += 0.428
            if p in {"'s", '’s'}: strength += 0.216
    if p in ADVERBS and q in HAVE: strength += 0.591
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else []
    raw = prefix.token_strings[-1]
    w = raw.strip().lower()
    p, q, r = (tail + ['', '', ''])[:3]
    value = 0.0
    if raw.startswith(' '):
        if w in DETERMINERS:
            offset, gain = DETERMINERS[w]
            value = offset + gain * context_strength(p, q, r)
        if w in BE and p == 'there': value += 0.154
        if w == 'one':
            if p in {'the', 'this', 'only', 'exactly', 'least'}:
                value += 0.870
            if p in {'just', 'about'}: value += 0.396
            if p == 'no': value -= 0.219
        if w in {'a', 'an'} and p == 'such': value += 0.166
        if w in {'following', 'follows'} and p in {'the', 'as'}:
            value += 0.146
        if w == 'yet' and p == 'not': value -= 1.639
        if w in {'long', 'far'} and p in {'so', 'too', 'how', 'very'}:
            value -= 1.086
        if w == 'quite' and p in {'not', "n't", '’t'}: value -= 2.022
        if w == 'up' and p in {'come', 'came', 'coming'}: value -= 0.770
        if w == 'ahead' and p in {'go', 'going', 'just'}: value -= 1.163
        if w == 'step' and p == 'next': value -= 0.979
    return (doc, [w] + tail[:2]), float(value)

programs.haiku:
"""Determiners that introduce a new thing after a verb of having or existence.

The component fires on a determiner ("a", "an", "this", "one", "another", "these") when
it opens the object or complement of a verb of having or existence, as in
    "There's this ..." (strongest), "there is also a ...", "I have a ...",
    "has only one ...", "is this ...".
It is near zero for determiners after a preposition or conjunction ("in a", "of this",
"from a", ", and a"). It only reads the words before the determiner.

The strength depends on the determiner ("this" > "one" > "a", "an", "another", "these")
and on the context before it, read from the table below.
"""

READS = ()

GROUP = {" this": "this", " one": "one", " a": "other", " an": "other",
         " another": "other", " these": "other"}

# typical activation, by determiner group and by the context before the determiner
STRENGTH = {
    "this": {"exist": 4.7, "have": 3.3, "limit": 0.55, "be": 0.9, "other": 0.25, "prep": 0.02},
    "one": {"exist": 2.75, "have": 1.1, "limit": 1.07, "be": 0.45, "other": 0.33, "prep": 0.2},
    "other": {"exist": 1.55, "have": 0.6, "limit": 0.3, "be": 0.03, "other": 0.03, "prep": -0.03},
}

HAVE_VERBS = {"have", "has", "had", "got", "having", "found", "encounter", "shared"}
LIMITERS = {"only", "least", "all"}
BE_VERBS = {"is", "was", "are", "be", "were", "'s", "’s"}
PREPOSITIONS = {"in", "of", "from", "for", "by", "that", "because", "during", ",", "within",
                "under", "between", "through"}


def word_before(prefix, back):
    """The word `back` tokens before the current one, or '' before its document starts."""
    i = len(prefix) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def context(prefix):
    prev = word_before(prefix, 1)
    if any(word_before(prefix, back) == "there" for back in (1, 2, 3)):
        return "exist"
    if prev in HAVE_VERBS:
        return "have"
    if prev in LIMITERS:
        return "limit"
    if prev in BE_VERBS:
        return "be"
    if prev in PREPOSITIONS:
        return "prep"
    return "other"


DEGREE_WORDS = {"long", "far", "fast", "quite", "yet", "hard", "big", "bad", "late", "early",
                "easy", "difficult", "large", "high", "strong", "good", "little", "often",
                "surprising", "surprisingly", "exactly", "later", "small", "old", "much", "many",
                "soon", "well", "deep", "short", "slow", "close", "simple", "common", "likely"}
STRONG_DEGREE = {"long", "far", "fast", "quite", "yet"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in DEGREE_WORDS and word_before(prefix, 1).lower() in ("how", "too", "not"):
        return None, -2.5 if word in STRONG_DEGREE else -0.6
    group = GROUP.get(prefix.token_strings[-1])
    if group is None:
        return None, 0.0
    return None, STRENGTH[group][context(prefix)]

programs.sol:
"""Plural presentation, existence and questions about a collection.

Recognize `there are/were`, `here are`, `what are` and `how do`, including
short continuations into determiners and number-leading spaces. Several
other languages' existential constructions behave similarly. Document
separators, repeated middle dots and a new record's title label are separate
formatting responses. All rules use only a short preceding text suffix.
"""
import re

READS = ()
QUANTIFIERS = {'one', 'two', 'most', 'each', 'all', 'some', 'few', 'many'}
COLLECTIONS = {'kinds', 'types', 'names', 'examples', 'sorts', 'set', 'list'}
ADVERBS = {'also', 'still', 'now', 'always', 'often', 'certainly', 'already'}
PLURAL_COPULAS = {
    'sont': 0.8, 'sind': 0.5, 'zijn': 2.1, 'são': 1.5,
    'werden': 0.5, 'wurden': 1.4, 'waren': 1.0,
}


def response(token, before):
    if token == '<|endoftext|>':
        return 1.55
    if len(token) >= 2 and set(token) == {'·'}:
        return 1.13
    before = before.replace('\\n', '\n')
    word = token.strip()
    ending = before + token
    if re.search(r'(?i)\bexist(?:en|em)$', ending):
        return 5.5
    if ending.endswith('一些'):
        return 3.2 if '是' in ending[-8:] else 1.5
    if token[:1].isalpha() and before[-1:].isalpha():
        return 0.0  # A piece of a word, not a grammatical word.
    # Last words: case distinguishes sentence openings from embedded clauses.
    words = re.findall(r'[^\W\d_]+', before[-100:])
    raw_prev = words[-1] if words else ''
    prev = raw_prev.lower()
    prev2 = words[-2].lower() if len(words) > 1 else ''
    recent = [w.lower() for w in words[-5:]]
    raw_subject = raw_prev
    if prev in ADVERBS and len(words) > 1:
        raw_subject = words[-2]
    subject = raw_subject.lower()
    capital = raw_subject[:1].isupper()

    if word in {'are', 'were', 'aren', 'weren'}:
        strength = {
            'there': 10.4 if capital else 8.7,
            'here': 5.9 if capital else 4.7,
            'what': 3.9, 'these': 3.4 if capital else 2.2,
            'those': 3.0, 'which': 0.7,
            'who': 3.1 if capital else 0.6,
            'you': -1.5 if capital else -0.5,
            'we': -0.5 if capital else -0.2,
        }.get(subject, 0.13)
        if (subject == 'there' and not capital
                and re.search(r'how many[^.!?;\n]*$', before[-85:], re.I)):
            strength = 5.5  # Embedded counting question: how many there are.
        if word in {'were', 'weren'}:
            strength = strength * 0.65 if strength > 1 else 0.08
        if word in {'aren', 'weren'}:
            strength *= 0.5
        if word == 'are' and before.strip() == 'What':
            strength = 6.7
        return strength
    if token in {"'t", '’t'} and prev in {'aren', 'weren'}:
        return 3.2 if 'there' in recent else 0.0
    if word == 'there':
        if prev == 'are':
            return 9.6 if raw_prev[:1].isupper() else 6.1
        return 3.3 if prev == 'were' else 0.02
    if word == 'exist' and prev == 'there':
        return 4.9
    if word in {'be', 'been', 'have'} and 'there' in recent:
        if word == 'have':
            return 3.8 if prev == 'there' else 0.0
        if word == 'been':
            conditional = {'could', 'should', 'would', 'may', 'might'}
            if any(w in conditional for w in recent):
                return 0.7
            if 'have' in recent:
                return 5.6
            return 2.3 if 'had' in recent else 0.0
        if 'seem' in recent or 'need' in recent:
            return 4.0
        return 2.3 if 'may' in recent or 'must' in recent else 0.9
    if word == 'do':
        if before.strip() in {'What', 'How'}:
            return 5.3
        return {'what': 3.1, 'how': 2.0, 'where': 1.8, 'why': 1.1}.get(prev, 0.0)
    if word == 'the':
        if prev in {'are', 'were'}:
            if raw_prev[:1].isupper():
                return 3.8
            return {'what': 4.3, 'these': 3.0, 'those': 3.0,
                    'there': 3.7, 'here': 3.0, 'which': 2.0}.get(prev2, 1.2)
        if prev == 'of':
            if raw_prev[:1].isupper():
                return 4.7
            if prev2 in QUANTIFIERS:
                return 1.05
            return 0.8 if prev2 in COLLECTIONS else 0.04
