    body = token.strip()
    if body.startswith("<|") and body.endswith("|>"):
        return "special"
    if "_" in token:
        return "ident"
    if body == "":
        return "blank"
    if body.isalpha():
        return "word"
    if body.isdigit():
        return "number"
    if not any(ch.isalnum() for ch in body):
