CODE_TOKENS = {"{", "(", "[", "\t", "__", "_", '"', ' "', "import", "::", "|", '="', "$", "))", "}}", "text", "org", "begin", "span", "td"}
MARKUP_TOKENS = {".py", ".js", ".md", ".rs", ".yml", "```", "<|im_start|>", "user", "@@", "+++", ".txt", ".com", "php", ".lastname", "'s"}


