            if n == 'j':
                v -= 1.4667
            if len(n) <= 2 and n[:1] in ('b', 'v', 'k', 'w'):
                v -= 0.3805
            if n.startswith(('ak', 'ad', 'ast')):
                v += 1.0684
            if n.startswith('ix'):
                v -= 0.0833
        if p == 'fu' and n[:1].isalpha() and not regex.search(r'\p{Script=Han}', s):
            v -= 0.0875
    return (doc, s, (tail + b)[-4:]), float(v)

"""Recognize written numbers ending in one, especially 11 and 21.

A one continuing a numeral is usually negative; earlier digits damp that
signal. Decimal notation weakens it, line numbers and Chinese date units
strengthen it. A leading zero has a separate, often positive effect.
Eleven, eleventh, compound numbers ending in one, Roman XI, and November
supply related lexical signals. Initial ones/twos have boundary corrections;
seven has a small negative baseline. This is a text-rule approximation, not a
model of the component's smaller, miscellaneous lexical responses.
"""

import unicodedata

READS = ()
DIGITS = '0123456789'
TENS = {'twenty', 'thirty', 'forty', 'fifty', 'sixty',
        'seventy', 'eighty', 'ninety'}


def is_digit(token):
    return len(token) == 1 and token in DIGITS


def strength(digit):
    if digit in '12':
        return 2.5
    if digit in '34':
        return 1.3
    return 1.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        prev, before, blank, number_line, tail, initial_ones = (
            '', '', True, False, '', True)
    else:
        _, prev, before, blank, number_line, tail, initial_ones = carry
    token = prefix.token_strings[-1]
    lower = token.strip().lower()
    value = 0.0

    if token == '1':
        if initial_ones:
            value = 0.63
        elif is_digit(prev):
            if prev == '0':
                if is_digit(before):
                    value = -0.18 if before in '12' else -0.28
                elif before.endswith('.'):
                    value = -0.22
                elif before.endswith('-'):
                    value = 0.8
                elif before.endswith('/'):
                    value = 0.42
                else:
                    value = 0.15
            else:
                value = -strength(prev)
                if is_digit(before):
                    if before == '1':
                        value *= 0.39
                        if prev == '1':
                            value = -0.37
                    else:
                        value *= 0.81 if before == '0' else 0.62
                elif before.endswith('.'):
                    value *= 0.65
                elif before.endswith((',', ':', '=')):
                    value *= 0.8
                if number_line:
                    value *= 1.13
                if before.endswith(('年', '月')):
                    value *= 1.35
        elif prev in ('.', ',', '-') and is_digit(before):
            factor = {'.': 0.36, ',': 0.19, '-': 0.08}[prev]
            value = -strength(before) * factor
            if before == '0':
                value = -0.18 if prev == '.' else -0.02
        elif prev.endswith('_'):
            value = -0.25
        elif '\n' in prev:
            value = 0.12
    elif token == '2' and initial_ones:
        # At the document boundary, initial 1s and a following 2 differ.
        value = 0.41 if fresh else -3.33
    elif token in ('₁', '１'):
        if prev and prev[-1].isdigit():
            value = -2.2
    elif token == '一':
        if prev and 0 < unicodedata.numeric(prev[-1], 0) <= 10:
            value = -2.2
    elif lower == 'november':
        value = -1.76
    elif token.strip() in ('Nov', 'NOV'):
        value = -1.0
    elif token.strip() == 'XI':
        value = -1.75
    elif lower == 'eleven':
        value = -2.65 if token.strip().islower() else -2.0
    elif (tail + token).lower().endswith('eleventh'):
        value = -4.4
    elif lower in ('one', '-one', 'first', '-first'):
        tens = prev.strip().lower().rstrip('-')
        if tens in TENS:
            value = -4.0 if tens == 'twenty' else -1.3
    elif token == '7':
        value = -0.077

    if is_digit(token) and not is_digit(prev):
        number_line = blank
    if '\n' in token:
        blank = not token.rsplit('\n', 1)[-1].strip()
    elif token.strip():
        blank = False
    initial_ones = initial_ones and token == '1'
    state = (doc, token, prev, blank, number_line,
             (tail + token)[-24:], initial_ones)
    return state, value

programs.haiku:
"""Component layers.1.mlp.down_proj:1771 as a "digit 1 inside a number" detector.

What it does: this component goes strongly negative on the digit "1" when the
"1" continues a number, i.e. when the token just before it is a digit. The
size depends on that digit and on where the "1" sits in the number:
  - a "1" that is the second digit of a number, after a "1" or "2"
    ("11", "21", "112"-style starts): about -2.5, the strongest response;
  - a "1" later in a longer number, after a "1" or "2": about -1.5;
  - a "1" after a digit 3-9: about -1.0 (second digit) or -0.7 (later);
  - a "1" after a "0": near zero.
A "1" that begins a number (after a space, newline, letter or bracket) stays at
zero. A "1" after a decimal point or thousands comma ("2.1", "8,100") is mildly
negative. The word "eleven" and the subscript one "₁" (as in a₁a₂) get a
similar strong negative value. Every other token gives 0.

Main program: `step` looks back only over the current number's digits (a few
tokens) and returns the value at the current position.
"""

DIGITS = set("0123456789")
READS = ()

AFTER_DECIMAL_OR_COMMA = -0.4  # "1" after "." or ","
SUBSCRIPT_ONE = -0.6           # "₁"
EVEN_WORDS = {" eleven": -2.0, " Eleven": -2.0}


def one_after_digit(prefix, t):
    """Value for a "1" at t whose previous token is a digit, from the number's digits."""
    docs = prefix.document_ids
    start = t - 1
    while start > 0 and prefix.token_strings[start - 1] in DIGITS and docs[start - 1] == docs[t]:
        start -= 1
    before = prefix.token_strings[t - 1]  # the digit just before the "1"
    second_digit = start == t - 1         # no other digit before it in this number
    if before in ("1", "2"):
        return -2.5 if second_digit else -1.5
    if before == "0":
        return -0.1
    return -1.0 if second_digit else -0.7


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    if token in EVEN_WORDS:
        return carry, EVEN_WORDS[token]
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return carry, 0.0
    before = prefix.token_strings[t - 1]
    if token == "₁":
        return carry, SUBSCRIPT_ONE
    if token != "1":
        return carry, 0.0
    if before in DIGITS:
        return carry, one_after_digit(prefix, t)
    if before in (".", ","):
        return carry, AFTER_DECIMAL_OR_COMMA
    return carry, 0.0

programs.sol:
"""Approximate a sparse mixture of word and phrase responses.

For state/State, U.S. subdivision names, capitalization, articles,
possessives and a fixed set of technical adjectives set the magnitude.
A following 'of' inherits 65% of the predicted state response.
Other rules cover prepositional pronouns, use/store/place/case, short
phrases and attached S-U spellings. Unmatched tokens receive zero.
These rules capture recurring training patterns, not the irregular
negative word-piece responses.
"""
import pycountry

READS = ()
US_SUBDIVISIONS = tuple(' ' + s.name.lower()
                        for s in pycountry.subdivisions.get(country_code='US'))
PREPOSITIONS = set('of to for from with in on at into upon about by without '
                   'over under between among around through against'.split())
POSSESSIVES = set("my our your their its his her 's".split())
ARTICLES = {'the', 'a', 'an'}
NOMINAL_CONTEXT = ARTICLES | POSSESSIVES
IDIOMS = {
    ('place', 'of'): 0.75,
    ('in', 'general'): 1.75,
    ('as', 'much'): 0.83,
    ('as', 'to'): 0.69,
    ('as', 'such'): 1.65,
    ('present', 'day'): 0.42,
}
TECHNICAL_STATES = set('initial final previous starting next terminal steady '
                       'quantum ground solid coherent folded compressed broken '
                       'halt'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_value, tail = '', 0.0, ' '
    else:
        previous, previous_value, tail = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    prior = previous.strip()
    before = prior.lower()
    value = 0.0
    if word.lower() == 'state':
        title = word != 'state'
        if tail.lower().rstrip(' (').endswith(US_SUBDIVISIONS):
            value = 4.5 if tail.rstrip().endswith('(') else 5.4
        elif not token[:1].isspace():
            value = 1.5 if word.isupper() else 0.5
        elif before == 'the':
            value = 4.7 if title else 4.0
        elif before in {'a', 'an'}:
            value = 2.7 if title else 1.7
        elif before in {'this', 'that', 'these', 'those'}:
            value = 2.8 if title else 1.0
        elif before in POSSESSIVES:
            value = 3.0 if title else 3.4
        elif before in TECHNICAL_STATES:
            value = 0.2
        elif before == 'current':
            value = 6.0 if title else 4.8
        elif before == 'of':
            value = 1.5 if title else 1.8
        elif before == '.':
            value = 2.6 if title else 3.2
        elif previous[:1].isspace() and prior[:1].isupper():
            value = 2.7 if title else 1.3
        elif before.isalpha():
            value = 2.3 if title else 1.3
        else:
            value = 2.1 if title else 0.8
    elif word == 'of' and before == 'state':
        value = 0.65 * previous_value
    elif (before, word) in IDIOMS:
        value = IDIOMS[before, word]
    elif word in {'it', 'them', 'us'} and token.startswith(' '):
        if before in PREPOSITIONS:
            if word == 'it':
                value = 2.7 if before == 'of' else (
                    1.5 if before in {'about', 'in', 'on'} else 0.95)
            elif word == 'them':
                value = 1.2 if before == 'of' else (
                    0.85 if before in {'in', 'on'} else 0.35)
            elif before == 'of':
                value = 0.7
    elif word == 'use' and token.startswith(' '):
        if before in NOMINAL_CONTEXT | {'no', 'any'}:
            value = 1.1
        elif before in {'in', 'on', 'for', 'of'}:
            value = 0.8
    elif word.lower() == 'store' and token.startswith(' '):
        value = 0.6
        if before in NOMINAL_CONTEXT:
            value = 1.1
        elif before in {'app', 'web', 'in'}:
            value = 1.7
        elif before in {'to', 'will', 'can', 'def', 'we', 'they', 'you', 'if'}:
            value = 0.0
    elif word in {'U', 'Us', 'u'} and token == word and before.endswith('s'):
        if word == 'u':
            value = 1.1
        elif prior.isupper():
            value = 6.5 if word == 'U' else 5.0
            if len(prior) > 2:
                value = 2.5
    elif word == 'case':
        if before in POSSESSIVES:
            value = 1.0
        elif before in {'this', 'any'}:
            value = 0.5
        elif before == 'the':
            value = 0.28
    elif word == 'place':
        if before in POSSESSIVES:
            value = 1.7
        elif before == 'the':
            value = 1.0
        elif before in {'in', 'from'}:
            value = -0.45
    elif word.lower() == 'states' and token.startswith(' '):
        value = 0.3
    return (doc, token, value, (tail + token)[-80:]), value

programs.haiku:
"""Layer-1 MLP unit 1772 (down_proj): a lexical "phrase-ending word" detector.

What it responds to. The unit fires on a few words that end a fixed phrase:
  - "state" / "State" / "states" / "Estado" in "in the state", "new state", "this State",
    "v. State" (strongest); and "of" right after "state" or "place" ("state of",
    "place of birth");
  - "general" in "in general";
  - "store" in "at the store"; "use" in "the use", "no use", "on use"; "case" in "this
    case"; "day" in "present day"; "much" in "as much"; "change" in "climate change";
  - "it" when it is the object of a preposition ("of it", "for it", "into it", "from it").
    As a subject ("it was") it stays at 0.
A trigger word gets its full value after a preposition or determiner ("the", "this",
"in", "of", "on", "as", ...). After any other word it gets half of that. Elsewhere 0.

What it predicts. Each trigger has a fixed typical activation, scaled to fit the eval
rows. Everything else is 0. It uses only the token and the token before it, within
the same document.

Why. These are the high-activation cases in the harvest. The negative activations
(on mid-word subword pieces of rare words) have no simple rule here and are not modelled.
"""

READS = ()

# Trigger word -> typical activation when it follows a preposition or determiner.
TRIGGERS = {
    "state": 2.25, "states": 0.9, "estado": 0.4, "general": 1.9, "use": 0.9, "store": 1.0,
    "case": 0.8, "much": 0.8, "day": 0.6, "change": 0.5,
}
# "it" fires only as the object of a preposition; this is its typical activation there.
IT_VALUE = 0.9
# Words that set up a noun-phrase or object slot before a trigger.
SLOT_BEFORE = {
    "the", "this", "that", "a", "an", "new", "in", "of", "on", "for", "into", "from", "at",
    "no", "as", "by", "to", "present", "its", "their", "his", "her", "any", "some",
}
PREPOSITIONS = {"of", "on", "for", "into", "from", "to", "at", "in", "with", "by", "about"}


def step(carry, prefix, upstream):
    """Activation at the newest token, from that token and the one before it."""
    tok = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if tok in TRIGGERS:
        value = TRIGGERS[tok] if prev in SLOT_BEFORE else 0.5 * TRIGGERS[tok]
    elif tok == "it":
        value = IT_VALUE if prev in PREPOSITIONS else 0.0
    elif tok == "of" and prev in ("state", "states", "place"):
        value = 1.1
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A document-opening transient, with a coarse lexical/formatting response.

The signal is large on an opening token and stays large if that same token
simply repeats. After the first different token, predict zero. Opening
articles, quantifiers, possessives and ordinals tend negative; capitals and
longer text tend positive. Very frequent English words receive a penalty.
This approximates lexical variation rather than memorizing token identities.
"""
from functools import lru_cache
import inflect
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'an', 'the'}
QUANTIFIERS = set('some any many much few all each every more most less least '
                  'other another both enough several'.split())
POSSESSIVES = set('my your his her its our their'.split())
PREPOSITIONS = set('of in to for on at by from with as into about over under '
                   'between through after before without during'.split())
CONJUNCTIONS = set('and or but nor yet so'.split())
_engine = inflect.engine()
ORDINALS = {_engine.number_to_words(_engine.ordinal(i)) for i in range(1, 11)}
ORDINALS.update(('last', 'next', 'previous'))
NUMBERS = {_engine.number_to_words(i) for i in range(1, 21)}


@lru_cache(maxsize=32768)
def opening(s):
    t = s.strip()
    if s == '\x00':
        return -13.02
    if s == r'\t':
        return -8.94
    if len(t) > 1 and set(t) == {'·'}:
        return 4.49
    if not t:
        if s == '\n':
            return -2.76
        if s == ' ':
            return -0.71
        if s == '\t':
            return -0.25
        if s == '\n\n':
            return 1.11
        if '\xa0' in s:
            return 3.54
        return 0.8
    if s.startswith('<|') and s.endswith('|>'):
        return 2.73 if s == '<|endoftext|>' else -0.19
    if t in {'.', ',', ':', ';', '|', '#'}:
        if t == '.':
            return 1.88
        if t == ',':
            return 1.15
        if t == '#':
            return -0.99
        return -0.65
    if t.startswith('#!'):
        return -0.9
    if t.startswith('<?'):
        return 5.29
    if t.isdigit():
        return -0.35

    low = t.lower()
    cap = t[0].isupper()
    space = s.startswith(' ')
    frequency = zipf_frequency(low, 'en')
    value = 1.13 + 0.14 * min(len(t), 16)
    value -= 0.19 * max(0.0, frequency - 5.0) ** 2
    value += 1.31 * cap - 0.35 * t.isascii()
    value -= 0.23 * (len(t) == 1) + 0.09 * t.isalpha()
    if low in ARTICLES:
        value -= 1.35 + 3.57 * space
    if low == 'the':
        value += -2.4 + 1.86 * cap
    if low in QUANTIFIERS:
        value -= 2.56
    if low in ORDINALS:
        value -= 4.07
    if low in POSSESSIVES:
        value -= 2.73
    if low in NUMBERS:
        value -= 2.99
    if low in PREPOSITIONS and space:
        value -= 0.97
    if low in CONJUNCTIONS:
        value += 1.03
    if t in {'(', '[', '{'}:
        value -= 1.99
    if t in {'/', '//', '/*'}:
        value -= 1.87
    if t in {chr(34), chr(39), '`', chr(34) * 3}:
        value -= 2.19
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, opening(prefix.token_strings[-1]), True)
    else:
        old_doc, first_token, value, unchanged = carry
        carry = (doc, first_token, value, unchanged and token == first_token)
    return carry, carry[2] if carry[3] else 0.0

programs.haiku:
"""layers.1.mlp.down_proj:1773: a "first token of a document" feature.

The component is silent almost everywhere. It fires on the first token of a document: the
first token of a packed row, or the first token after a document boundary (<|endoftext|>).
There the model sees nothing before that token (attention never crosses documents), so the
activation depends only on which word or symbol opens the document, and its sign follows
the kind of word:

  * a lowercase determiner or quantifier after a space, mid-sentence "the", "a", "an",
    "our", "my", "your", "any", "every", "two", "first", ...: strongly negative
    (" the" about -7.6, the other determiners about -5);
  * other determiners and prepositions (in, from, with, of, ...), and punctuation,
    brackets, quotes and whitespace: slightly negative (about -0.7);
  * pronouns, auxiliaries and conjunctions (you, we, is, and, ...): about +1;
  * ordinary words: positive, more for capitalised words (names, titles, headings, about
    +2.5) than lowercase ones (about +1.5); other symbols and non-Latin text about +0.5.

Separately, the middle-dot filler "··" (dot leaders in tables) gives about +4.5 at every
position, wherever it occurs. Everywhere else the component is near 0, so the program
predicts 0 there.

Only the newest token and the document labels are read; no carry is needed. The values are
rounded class averages. Within a class the activation varies by word in ways these
categories don't capture, which is where the remaining variance is.
"""

READS = ()

DETERMINERS = set(
    "the a an this that these those my your his her its our their every each any some no all "
    "both two three four five six first second third fourth last next other another many several few".split()
)
PREPOSITIONS = set(
    "in on at from with by for of to into over under about after before between through during "
    "as than".split()
)
PRONOUNS_AND_AUXILIARIES = set(
    "you we i he she it they me him us them who which what when where how why "
    "and or but if so because while although is are was were be been being have has had do does "
    "did can could will would should may might must".split()
)
OPENERS = set("([{<\"'=/#*\\|")


def _is_document_start(prefix):
    if len(prefix.token_ids) == 1:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] == "\u00b7\u00b7":
        return None, 4.5  # dot-leader filler, e.g. in tables: a steady positive value
    if not _is_document_start(prefix):
        return None, 0.0
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if not word or all(ch in OPENERS or ch.isspace() for ch in text):
        value = -0.7
    elif word.isalpha():
        if word in DETERMINERS and text.startswith(" "):
            value = -7.0 if word == "the" else -5.0
        elif word in DETERMINERS or word in PREPOSITIONS:
            value = -0.7
        elif word in PRONOUNS_AND_AUXILIARIES:
            value = 1.0
        elif text.strip()[0].isupper():
            value = 2.5
        else:
            value = 1.5
    else:
        value = 0.5
    return None, float(value)

programs.sol:
"""Approximate several early lexical/context patterns, not every token's value.

Positive rules cover selected Chinese degree phrases, especially importance
and rank/level expressions. Negative rules cover judicial judgments and
degree-prefixed tokens containing 好 ('good').
There are also generic document-start biases and a strong response to
the colon in a document-initial 'Title:' label. Small unrelated lexical effects
are left at zero. CC-CEDICT supplies meanings rather than a token-ID table.
"""
from functools import lru_cache
import regex
import cedict

READS = ()
HAN = regex.compile(r'\p{Script=Han}+')
IMPORTANCE = regex.compile(
    r'(^|; )(important|significant|major|main|fundamental|crucial|pivotal|core)\b')
JUDGMENT = regex.compile(r'\b(verdict|judgment|to sentence)\b')
LEVEL = regex.compile(r'\b(level|grade|rank|step \(of stairs\))\b')
INTENSIFIERS = {'很', '非常', '极', '極', '很是', '更加', '十分', '特别', '太',
                '至关', '至關', '尤为', '尤為', '最为', '最為'}
EMBEDDED_DEGREE = ('最', '更', '很', '非常', '至关', '至關', '尤为', '尤為')


@lru_cache(maxsize=None)
def meanings(text):
    """Greedily read dictionary words of up to four Han characters."""
    important = judgment = level = False
    for run in HAN.findall(text):
        i = 0
        while i < len(run):
            for n in range(min(4, len(run) - i), 0, -1):
                glosses = cedict.glosses(run[i:i+n])
                if glosses:
                    break
            for gloss in glosses:
                important |= n >= 2 and bool(IMPORTANCE.search(gloss))
                judgment |= bool(JUDGMENT.search(gloss))
                level |= bool(LEVEL.search(gloss))
            i += n
    return important, judgment, level


def onset(word):
    if word.startswith('<|'):
        return -0.58
    if not word.strip():
        return -0.37
    return -0.14 if word[:1].isspace() else -0.22


def step(carry, prefix, upstream):
    word, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, position = ('', 0) if first else (carry[1], carry[2] + 1)
    if first:
        value = onset(word)
    elif position == 1 and previous == 'Title' and word.startswith(':'):
        value = 5.614
    else:
        important, judgment, level = meanings(word)
        value = -0.8 * judgment
        if previous == '最':
            value += 0.4 + 2.5 * important
        elif previous == '更':
            value += 0.1
        elif previous == '深' and HAN.search(word):
            value += 0.9
        if important:
            if word.startswith(EMBEDDED_DEGREE):
                value += 1.4
            elif previous in INTENSIFIERS:
                value += 1.0
        if level and previous in {'高', '中', '低', '初'}:
            value += 1.5
        if word.startswith(('最', '很', '更', '非常')) and '好' in word:
            value -= 0.5
    return (doc, word, position), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:1775: a near-silent component that acts mainly on a document's first token.

What it does, in plain terms:
- Everywhere except a document's first token it is essentially silent. Its activation there is
  small, diffuse noise (about 0.05 in size) that no simple rule captures, so the program predicts 0.
- On a document's first token, where the model has no earlier context, it has a larger,
  token-dependent activation. Its sign follows what kind of text the document opens with:
    * a code or markup symbol (#, ;, *, =, /, \\, &, [, {, <, ", ,) is positive, the strongest case;
    * a blank or newline start is weakly positive;
    * a digit is strongly negative;
    * an ordinary word is negative: more so when it has a leading space (" the", " is")
      than when bare ("The", "Person");
    * other symbols and non-Latin letters are weakly negative.

It reads only the newest token's text and the document ids, and keeps no state. The class
values are the mean activation per class over 2048 training rows, starting at each row's
document boundary. Its variance explained is small (about 0.03 on held-out rows).
"""

READS = ()

CODE_SYMBOLS = set("#;*=/\\&[{<\",")

# Mean activation on a document's first token, by the kind of its first visible character.
FIRST_TOKEN_MEAN = {
    "blank": 0.09,
    "code_symbol": 0.26,
    "digit": -0.32,
    "spaced_word": -0.17,
    "bare_word": -0.08,
    "other_symbol": -0.08,
    "non_latin": -0.12,
}


def first_kind(text):
    """The kind of a token's first visible character, from its text alone."""
    body = text.lstrip(" ")
    if body == "" or body.startswith("\n"):
        return "blank"
    c = body[0]
    if c.isdigit():
        return "digit"
    if c.isalpha():
        if ord(c) >= 128:
            return "non_latin"
        if text.startswith(" "):
            return "spaced_word"
        return "bare_word"
    if c in CODE_SYMBOLS:
        return "code_symbol"
    return "other_symbol"


def step(carry, prefix, upstream):
    # carry: the document id of the previous token (None at the row's first token).
    doc_now = prefix.document_ids[-1]
    starts_doc = prefix.position == 0 or prefix.document_ids[-2] != doc_now
    if not starts_doc:
        return doc_now, 0.0
    return doc_now, FIRST_TOKEN_MEAN[first_kind(prefix.token_strings[-1])]


if __name__ == "__main__":
    # Quick self-check on made-up document starts (the scorer does not run this).
    for word in ["2", "Person", " the", "#", " *", "\n", "é"]:
        print(repr(word), first_kind(word), FIRST_TOKEN_MEAN[first_kind(word)])

programs.sol:
"""Approximate a sparse code-syntax and document-boundary signal.

Equality/assignment, mathematical relations, `from ... import`, and statement
returns are positive; quotes opening printed/logged strings are negative.
An identifier longer than two characters strengthens spaced '='. Longer
module names strengthen 'import'. Separate opening-run rules cover digits,
whitespace/escapes, markers, and several declaration keywords.

Only a 160-character suffix and the identical-token opening run are retained,
reset at each document. Other cases are near zero: this deliberately omits
fine word-by-word and contextual variation.
"""
import re

READS = ()
PRINT_CALL = re.compile(
    r'(?:\b(?:print|printf|println|fprintf|puts|echo|write|writeln)'
    r'|\.(?:log|debug|info|warn|error)|\bPrint(?:ln|f)?)'
    r'!?\s*\(\s*(?:(?:stderr|stdout)\s*,\s*)?[rf]?$')
QUOTE = re.compile(r'[\\]*[\"\'](?:[\\]+[nrt]?)?$')
LEFT_NAME = re.compile(r'([\w.$]+)\s*$')
FROM_IMPORT = re.compile(r'\bfrom\s+([\w.]+)\s*$')


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    token = text.strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        opening, repeated, tail = text, True, ''
    else:
        _, opening, repeated, tail = carry
        repeated = repeated and text == opening
    value = 0.0

    if text == '<|endoftext|>':
        value = 8.67 if repeated else 1.46
    elif text == '<|im_start|>':
        value = -0.84 if repeated else 0.0
    elif repeated:
        if text == '\r':
            value = -1.6
        elif text in ('\\n', '\\t'):
            value = 6.0
        elif token.isascii() and token.isdigit():
            value = 2.35
        elif text.isspace():
            value = 0.9 if text == ' ' else 3.0
        elif '\n' in text or '\r' in text:
            value = 2.5
        elif len(token) > 1 and set(token) == {'^'}:
            value = 3.7
        elif token in ('function', 'void'):
            value = 6.4
        elif token in ('class', 'int', 'let', 'public'):
            value = 3.5
        elif token in ('.', '#', '(', '['):
            value = 0.0
        elif token in ('\"', "'"):
            value = -0.6
        elif token and not any(ch.isalnum() for ch in token):
            value = 0.65
        else:
            value = -0.08
    elif token in ('≈', '⇒'):
        value = 0.95 if token == '≈' else 0.75
    elif token in (':=', '<-'):
        value = 0.8 if token == ':=' else 1.0
    elif re.fullmatch(r'[)\]}]+=', token):
        value = 0.5
    elif token == '=':
        name = LEFT_NAME.search(tail)
        if text.startswith((' ', '\t')):
            value = 0.9 if name and len(name[1]) > 2 else 0.55
        else:
            value = 0.4
    elif token == 'import':
        module = FROM_IMPORT.search(tail)
        value = min(1.6, 0.6 + 0.035 * len(module[1])) if module else 0.0
    elif token == 'return':
        # A return at an indented line/statement boundary, not English prose.
        code = re.search(r'(?:^|[\n;{}:]|\\[nt])[ \t]*$', tail)
        value = (0.66 if text.startswith('\t') else 0.5) if code else 0.0
    elif token in ('(f', '(r') and PRINT_CALL.search(tail + text):
        value = -0.3
    elif QUOTE.search(token):
        combined = tail + text.rstrip()
        before_quote = combined[:QUOTE.search(combined).start()]
        if (PRINT_CALL.search(before_quote)
                or re.search(r'\becho\s*$', before_quote)
                or re.search(r'\b(?:cout|cerr|clog|LOG)\b[^\n]*<<\s*$',
                             before_quote)):
            value = -1.05 if "'" in token else -0.72
        elif token.startswith('('):
            value = -0.1
        elif '\\' in token:
            value = -0.05

    return (doc, opening, repeated, (tail + text)[-160:]), value

programs.haiku:
"""Layer-1 MLP down_proj, component 1776, as a readable rule set.

What it does: the component writes a signed signal that is large for
  * the end-of-text token `<|endoftext|>` (about 1.5), and
  * assignment operators in code: ` =`, `=`, `:=`, `)=`, `<-`, `=>`, `⇒`, `≈`.
    Plain variable declarations and bare `name =` lines (`const x =`, `model =`) are
    strongest (about 1.2), an assignment inside an open call or bracket is weak (0.2),
    and other `=` are moderate (0.6).
  * binding keywords: ` import` (0.9), `\\treturn` (0.6), ` return` (0.35), ` throw` (0.45).
It is negative for opening a string inside a call, `("`, `('`, `(f`, and for Java access
modifiers (about -0.3). Almost everywhere else it is near zero.

At the first token of a document, where there is no earlier context, its value depends on
what kind of token starts the text: end-of-text is huge (8.7); whitespace, digits and
backslash escapes are about 2.3; punctuation and code brackets about 1.5; tab-indented
identifiers 0.8; unindented words about 0; space-prefixed prose words about -0.2.

Predictions are a per-token rule, with no table of token ids. The main variance it leaves
unexplained is a diffuse, token-specific wobble of ±0.07 on ordinary tokens, and the spread
within prose-initial words at document start.
"""
import re

READS = ()

ASSIGN = {" =", "=", " :=", ")=", "}=", " <-", " ⇒", "=>", "≈", " ≈"}
KEYWORDS = {" import": 0.9, " return": 0.35, "\treturn": 0.6, " throw": 0.45}
OPEN_QUOTE = {"('", '("', "(f", '(\\"', "(\\'"}
MODIFIERS = {"public", "\tpublic", " public", " static", " protected", " private"}
DECL = re.compile(r"\b(const|let|var|final|static|private|public|int|String|double|float)\b")
BARE_NAME_LINE = re.compile(r"^\s*[A-Za-z_][\w.]*\s*$")
CODE_PUNCT = re.compile(r"[;{}\[\]()\\]")


def first_token_value(tok):
    """Activation for a token that opens a document (it has no earlier context)."""
    if tok == "<|endoftext|>":
        return 8.0
    if tok.isspace() or tok.strip().isdigit() or tok.startswith("\\"):
        return 2.3
    if re.fullmatch(r"[^\w\s]+", tok) or (CODE_PUNCT.search(tok) and not re.search(r"[A-Za-z]{2}", tok)):
        return 1.5
    if re.fullmatch(r"\t[A-Za-z_]\w*", tok):
        return 0.8
    if re.fullmatch(r"[A-Za-z]+", tok):
        return 0.05
    if re.fullmatch(r" [A-Za-z]+", tok):
        return -0.2
    return 0.0


def assignment_value(prefix):
    """Strength of an `=`-like operator, from the code on its line so far."""
    line = ""
    for s in reversed(prefix.token_strings[-14:-1]):
        if "\n" in s:
            line = s.split("\n")[-1] + line
            break
        line = s + line
    if line.count("(") > line.count(")") or line.count("[") > line.count("]"):
        return 0.2  # keyword argument, comparison or attribute inside brackets
    if DECL.search(line) or BARE_NAME_LINE.match(line):
        return 1.2  # declaration or plain `name =` statement
    return 0.6


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start:
        value = first_token_value(tok)
    elif tok == "<|endoftext|>":
        value = 1.5
    elif tok in ASSIGN:
        value = assignment_value(prefix)
    elif tok in KEYWORDS:
        value = KEYWORDS[tok]
    elif tok in OPEN_QUOTE:
        value = -0.35
    elif tok in MODIFIERS:
        value = -0.25
    else:
        value = 0.0
    return carry, float(value)

"""layers.1.mlp.down_proj:1777, predicted from the text.

This component is almost silent inside a document. Its large values come at the first
token after a document boundary (the token after <|endoftext|>, or the first token of a
row). There, attention can see nothing but that token itself, so the activation depends
only on the word:
- negation or yes/no-question openers ("Not", " not", "Is", "Does", "Are", "is") are
  strongly negative, about -7; " is" with a leading space is only mildly negative;
- other auxiliaries and modals ("was", "must", "always", "likely", "my", "we") are
  about -2.5;
- determiners, conjunctions, prepositions and "it" are mildly positive, about +0.4;
- every other opening word is slightly negative, about -0.2.
Elsewhere the program predicts 0. One rare case is also encoded: a colon directly after
a document-opening "Title" gives -19.8 (the same value in every occurrence seen).
"""

NEGATION_OR_QUESTION = {"not", "is", "are", "does", "do", "did", "cannot"}
AUX_OR_MODAL = {"was", "were", "be", "been", "can", "could", "should", "would", "will", "may",
                "might", "must", "always", "likely", "necessarily", "unless", "had", "has",
                "have", "never", "my", "we"}
FUNC = {"the", "a", "an", "this", "that", "these", "those", "some", "into", "between", "of",
        "in", "on", "to", "with", "for", "from", "at", "by", "and", "or", "it", "they", "one"}

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    doc_start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start:
        if word in NEGATION_OR_QUESTION:
            if word == "not" or not raw.startswith(" "):
                return carry, -7.0
            return carry, -1.5
        if word in AUX_OR_MODAL:
            return carry, -2.5
        if word in FUNC:
            return carry, 0.4
        return carry, -0.2
    if raw == ":" and prefix.token_strings[-2] == "Title":
        if t == 1 or prefix.document_ids[-2] != prefix.document_ids[-3]:
            return carry, -19.8
    return carry, 0.0

programs.sol:
"""A partial lexical and document-boundary approximation.

The largest modeled responses complete split East Asian words: self-related
compounds, relatives/friends, Japanese hon- compounds, and national names.
These are explicit lexical families, not a general semantic classifier.
Whole-word tokens do not trigger the split-word rules.

At a row/document start, length, case, script and English grammatical class
supply a coarse estimate. Role delimiters and a few opening conventions have
separate values. Elsewhere, selected lexical/prefix patterns, particles and formatting
marks fire. The previous-token state resets at document boundaries.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
HANGUL = regex.compile(r'\p{Script=Hangul}+')
# Suffixes in self-related compounds (pride, defence, reliance, etc.).
SELF_RELATED = frozenset('慰立体ら備备衛卫尊摸欺慢爆暴破耕寻尋设設傳传得底')
SELF_NEGATIVE = frozenset(('动', '定', '定义', '导', '断', '從', '从'))
# Hon- compounds for the main body, headquarters, home and performance.
HON_MAIN = frozenset(('体', '部', '家', '家の', '番'))
HON_EXTENDED = frozenset(('格', '命', '業', '音', '週', '氏'))
# Referential 'this paper/course/experiment/film/contract/journal'.
HON_DOCUMENT = frozenset((
    '教程', '论文', '课程', '实验', '内容', '规定',
    '指南', '题目', '片', '契', '刊',
))
SMALL_EFFECTS = {
    'を': -0.127, 'も': 0.099, '의': 0.164,
    ' для': -0.117, ' на': -0.063, ' за': -0.123,
    '<|im_start|>': -0.005, '<|im_end|>': -0.05, '<think>': -0.11,
    '··': -0.335, '․': 0.158,
}


# The first token of a document has a separate, coarse form-based response.
PRONOUNS = frozenset("i you he she it we they me him her us them".split())
CONJUNCTIONS = frozenset("and or but nor yet so".split())
PREPOSITIONS = frozenset(
    "of in on to at from with by for into as about over under".split()
)


def opening_value(token):
    word = token.strip()
    low = word.lower()
    value = 0.03 if token[:1].isspace() else -0.11
    value -= 0.33 * (len(word) > 6)
    value += 0.31 * (len(word) == 1)
    value -= 0.04 * word.islower()
    value += 0.05 * word.istitle()
    value -= 0.33 * (bool(word) and all(c in '()[]{}（）【】' for c in word))
    value += 0.30 * (bool(word) and all(c in ':;：；' for c in word))
    value += 0.23 * bool(regex.fullmatch(r'\p{Script=Cyrillic}+', word))
    value -= 0.48 * bool(HANGUL.fullmatch(word))
    value -= 0.22 * (low in PRONOUNS)
    value += 0.30 * (low in CONJUNCTIONS)
    value += 0.16 * (low in PREPOSITIONS)
    if word.isascii() and word.isalpha():
        value += 0.055 * (3 < zipf_frequency(low, 'en') <= 6)
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    value = SMALL_EFFECTS.get(token, 0.0)
    if start:
        value = opening_value(token)
        if token == '<|im_start|>':
            value = -0.89
        elif token == '<|im_end|>':
            value = -0.81
        elif token.strip() == 'public':
            value = 1.6 if token.startswith('\t') else 2.9
        elif token == 'So':
            value = -1.6
        elif token == '<|endoftext|>':
            value = 2.85
        return (doc, token), value

    previous = carry[1].strip()
    if previous == '自':
        if token in SELF_RELATED:
            value = 1.3
            if token == '慰':
                value = 0.67
            elif token == '慢':
                value = 3.2
        elif token in SELF_NEGATIVE:
            value = -0.8
    elif previous == '本':
        if token in HON_MAIN:
            value = 3.0
        elif token in HON_EXTENDED:
            value = 1.8
        elif token in HON_DOCUMENT:
            value = -1.4
        elif token == '店':
            value = 0.65
    elif previous == '子' and token in ('供', '育'):
        value = 2.9
    elif previous == '兄' and token == '妹':
        value = 3.8
    elif previous in ('弟', '学') and token in ('妹', '弟'):
        value = 2.1
    elif previous in ('幼', '男の') and token == '子':
        value = 0.6
    elif previous == '友' and token == '達':
        value = 1.25
    elif previous == '兄弟' and token == '姊妹':
        value = 0.7
    elif previous == '亚' and HAN.fullmatch(token):
        value = 0.75
    elif previous == '자' and HANGUL.fullmatch(token):
        value = 0.85
    elif previous == '中国' and token in ('共产党', '共产'):
        value = -2.3
    elif previous == '中华' and token == '民国':
        value = -3.2
    elif previous == '人民' and token in ('共和', '共和国', '解放军'):
        value = -2.8
    elif previous == '共和' and token == '國':
        value = -2.7
    elif previous == '美':
        if token in ('金', '梦', '模', '展'):
            value = -0.95
        elif token == '少女':
            value = 1.2
    elif previous == '甲' and token == '虫':
        value = -2.2
    elif previous == '他' and token in ('に', '社'):
        value = 1.6
    elif previous == '公':
        if token in ('函', '文', '關'):
            value = -0.4
        elif token == '仔':
            value = 2.2
        elif token == '認':
            value = 0.5
    return (doc, token), value

programs.haiku:
"""Layer-1 MLP down-projection feature 1780: the 'perfect tense + frequency adverb' feature.

In plain terms: this component writes a positive signal when the text is in a
present-perfect or habitual frame, most strongly on the word "been" and on frequency
adverbs ("always", "never", "ever", "often") that sit right after have/has/had or
I've, as in "has always been", "I have never", "People have always". It is weakest
(near zero or slightly negative) on time words that interrupt or anchor such a phrase
("has already", "have just", "has yet", "currently", "until"). Quantity and
time-span words ("many", "a lot of", "life", "career", "history", "times") give a
small positive push. Everything else is predicted as 0.
"""

READS = ()

# Present-perfect auxiliaries (written as they appear as tokens, lowercase).
PERFECT_AUX = {"have", "has", "had", "'ve", "’ve"}

# Frequency / habitual adverbs, with a few common foreign equivalents.
FREQUENCY = {
    "always", "never", "ever", "often", "usually", "sometimes", "frequently",
    "generally", "constantly", "seldom", "rarely", "occasionally", "repeatedly",
    "sempre", "toujours", "souvent", "immer", "一直", "始终",
}

# Quantity and time-span words that usually sit inside a longer phrase.
TIME_SPAN = {
    "many", "lot", "times", "occasions", "life", "career", "history", "extent",
    "course", "long", "general", "degree", "vezes", "veces", "fois",
}

# Time words that interrupt a perfect phrase ("has already", "have just").
INTERRUPTER = {"already", "just", "now", "yet", "still", "also", "not", "recently"}

# Time/aspect words that tend to be negative anywhere.
NEGATIVE = {"available", "looking", "until", "currently", "already", "yet"}

# Words after which "of" is a quantity phrase ("a lot of", "one of", "number of").
QUANTITY_HEAD = {"lot", "number", "one", "many", "few", "bit", "couple", "variety", "majority"}

# Common past participles, which follow have/has in perfect tenses.
PARTICIPLE = {
    "seen", "done", "become", "known", "made", "taken", "given", "shown", "gone",
    "heard", "met", "come", "found", "read", "written", "spent", "begun", "brought",
}


def step(carry, prefix, upstream):
    """Return this position's predicted activation. `carry` is unused: each step looks
    only at the newest word and the word before it, within the same document."""
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    after_aux = prev in PERFECT_AUX

    if word == "been":
        value = 3.3 if prev in FREQUENCY else 1.2
    elif word in FREQUENCY:
        value = 3.0 if after_aux else 0.4
    elif word in TIME_SPAN:
        value = 0.25
    elif word == "of" and prev in QUANTITY_HEAD:
        value = 0.35
    elif after_aux and word in INTERRUPTER:
        value = -0.35
    elif word in NEGATIVE:
        value = -0.2
    elif after_aux and (word.endswith("ed") or word in PARTICIPLE):
        value = 0.15
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A Portuguese-conditioned spelling signal, dominated by the articles a/as.

Completed words supply a short, decaying estimate of Portuguese versus other
European languages, using corpus word frequencies. In Portuguese
context the articles a/as/o/os respond positively, especially lowercase ' a'.
Short est-/ess- beginnings also respond. Case, spacing, and a preceding
'com' or 'para' adjust the article response.
Other alphabetic pieces get a weak negative background in Portuguese context.
The large, irregular positive and negative word-piece spikes remain unmodeled.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'as', 'o', 'os'}
EST_PARTS = {'est', 'este', 'esta', 'estes', 'estas'}
ESS_PARTS = {'ess', 'esse', 'essa', 'esses', 'essas'}
POSITIVE_PARTS = ARTICLES | EST_PARTS | ESS_PARTS


@lru_cache(maxsize=50000)
def language_evidence(word):
    portuguese = zipf_frequency(word, 'pt')
    other = max(zipf_frequency(word, language)
                for language in ('en', 'es', 'fr', 'it', 'de', 'hu'))
    if max(portuguese, other) < 2.0:
        return 0.0
    return max(-2.0, min(2.0, portuguese - other))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, '')
    _, word, evidence, previous_word = carry
    text = prefix.token_strings[-1]
    continued = bool(word) and text[:1].isalpha()
    for ch in text.lower():
        if ch.isalpha():
            word += ch
        elif word:
            evidence = 0.90 * evidence + language_evidence(word)
            evidence = max(-10.0, min(10.0, evidence))
            previous_word, word = word, ''
    gate = max(0.0, min(1.0, evidence / 4.0))
    token = text.strip()
    lower = token.lower()
    base = 0.0
    response = -0.10 if lower.isalpha() and lower not in POSITIVE_PARTS else 0.0
    if not continued:
        if lower == 'a':
            base = -0.04
            if token.isupper():
                response = 3.3
            elif text[:1].isspace():
                response = 3.2 if previous_word in {'com', 'para'} else 6.1
            else:
                response = 2.5
        elif lower == 'as':
            base, response = -0.02, 2.6
        elif lower in {'o', 'os'}:
            response = 1.0
        elif lower in EST_PARTS:
            base = -0.15
            response = 3.4 if lower == 'est' else 2.0
        elif lower in ESS_PARTS:
            response = 1.8 if lower == 'ess' else 1.2
        if response > 0.0 and lower != 'a' and token[:1].isupper():
            response *= 0.60
    return (doc, word, evidence, previous_word), base + gate * (response - base)

"""Approximate a document-start transient using readable token classes.

Large training responses concentrate at document starts and initial runs
of identical tokens. Spaces, selected punctuation, zero, auxiliary verbs
and conditional markers get positive pulses; programming type names,
function declarations and some letter shapes get negative ones.

Keep the pulse while the initial token repeats, then predict zero.
This omits individual lexical differences and later fluctuations.
"""
import unicodedata

READS = ()
AUXILIARIES = frozenset('am is are was were be have has had do does did '
                        'can could will would shall should must may might'.split())
CURRENCY_SIGNS = frozenset('$€£¥₹')
TYPE_NAMES = frozenset('int integer str string float double bool boolean '
                       'char byte short long object void null none'.split())


def initial_value(text):
    if text.startswith('<|'):
        return 0.0
    if text and set(text) == {' '}:
        return 2.1
    if text == ' .':
        return 4.86
    if text and set(text) == {'·'}:
        return 1.88
    if text.startswith('#!'):
        return 2.8
    if text in {',', '.', '-', '#'}:
        return 2.1
    if text == ':':
        return 0.75
    if text == '0':
        return 1.83
    if text == '1':
        return -0.9
    if len(text) == 1 and unicodedata.category(text) == 'Pe':
        return 1.6
    stripped = text.strip()
    if stripped in CURRENCY_SIGNS:
        return 2.1
    if stripped == '%':
        return 2.8
    if not stripped:
        return -0.3
    if '\ufffd' in text:
        return 0.5
    if stripped.lower() in {'if', 'unless'}:
        return 2.1
    if stripped.lower() in TYPE_NAMES:
        return -2.8
    if stripped in {'def', 'function'}:
        return -3.5
    if text == stripped and text.lower() in AUXILIARIES:
        return 2.3
    if text.isupper() and all(unicodedata.name(c, '').startswith('CYRILLIC')
                              for c in text):
        return 1.7
    if text.isascii() and text.isalpha():
        if len(text) == 1 and text.islower():
            return -1.0
        if text.istitle() and len(text) >= 5:
            return -0.8
    if text.startswith(' ') and stripped.isascii() and stripped.isalpha():
        return -0.24
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        return (doc, token, value, True), value
    _, first, value, initial_run = carry
    initial_run = initial_run and token == first
    return (doc, first, value, initial_run), value if initial_run else 0.0

