PUNCT = {",", ".", "#", ")", "-", "%", "--", "###", "$", "+", "="}
AUX = {"is", "are", "was", "were", "be", "do", "does", "did", "have", "has", "had", "can",
       "will", "would", "should", "may", "might", "must"}
