          "driver", "speaker", "parent", "mother", "father"}
NAMES = {"john", "william", "richard", "michael", "david", "mark", "steven", "harry",
         "donald", "robert", "kevin", "daniel", "brian", "thomas", "paul", "tom", "bob"}
GREET = {"hello", "hi", "welcome", "dear", "hey", "let", "wait", "show", "find", "go",
         "note", "remember", "consider", "please", "enter", "first", "next"}
PRON = {"you", "we", "they", "that", "your", "their", "to", "with", "by", "from", "there",
