"""A partial formatting approximation, not a content model.

The strongest rule is a negative pulse on the opening ``Title:`` colon;
the remaining rules capture weaker formatting and startup effects.

Recognize opening title metadata (plain text or YAML), and the transition
out of a thinking block. At document starts, use coarse token-shape
backgrounds, with an extra negative pulse for source-code import directives.
Other positions have a near-zero background.
"""
READS = ()
IMPORT_DIRECTIVES = {'import', 'from', 'package', 'using', '#include'}


def opening_value(token):
    word = token.strip()
    if word in IMPORT_DIRECTIVES:
        return -0.55
    if not word:
        return -0.115
    if word.startswith('<|'):
        return -0.048
    if word.isdigit():
        return 0.171
    if word.isascii() and word.isalpha():
        return -0.082 if word[0].isupper() else -0.149
    if word.isalpha():
        return -0.068
    return -0.086


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
        yaml_header = token == '---\n'
    else:
        _, previous, position, yaml_header = carry
        position += 1
    value = opening_value(token) if position == 0 else 0.0027
    if position == 1 and previous == 'Title' and token == ':':
        value = -7.979
    elif yaml_header:
        if position == 0:
            value = 0.178
        elif position == 1 and token == 'title':
            value = 0.224
        elif position == 2 and previous == 'title' and token == ':':
            value = 0.513
    if token == '<think>':
        value = -0.077
    elif token == '</think>':
        value = 0.060
    elif token == '\n\n':
        if previous == '<think>':
            value = 0.079
        elif previous == '</think>':
            value = 0.147
    return (doc, token, position, yaml_header), value

"""A spelling-sensitive response to RUN and other R-vowel combinations.

The negative response grows for runner, code-member spellings, test-log
headings, and RUN split across tokens. A short text tail recognizes those
splits, including rerun. Some long-vowel R-spellings give a positive
response instead. Other tokens get zero. State resets per document.
This is a spelling rule, not a detector of motion in general.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '')
    if carry is not None and carry[0] == doc:
        previous, tail = carry[1:]
    token = prefix.token_strings[-1]
    word = token.lstrip(' ._-/')
    lower = word.lower()
    tail_lower = tail.lower()
    spaced = token[:1].isspace()
    value = 0.0

    if re.fullmatch(r'run(?:s|ning|ners?)?|ran', lower):
        if lower.startswith('runner'):
            value = -5.2 if spaced else -7.5
            if word[:1].isupper() and not spaced:
                value = -5.8
        elif lower == 'running':
            value = -3.0 if word.islower() and spaced else -2.4
        elif lower == 'ran':
            value = -3.8 if spaced or not previous[-1:].isalpha() else 0.0
        else:
            value = -2.7 if lower == 'runs' else -3.2
            if not spaced:
                value -= 0.8
        if token.startswith('.'):
            value -= 1.3
        if word == 'RUN' and spaced:
            value = -6.2 if tail.rstrip().endswith('===') else -3.8
        if token.startswith('-') and previous.strip().lower() == 're':
            value = -9.0
        if previous.strip().lower() in ('long', 'longest'):
            value *= 0.3
    elif re.fullmatch(r'rac(?:e[ds]?|ers?)', lower):
        value = -1.4
    elif lower == 'racing':
        value = -0.7
    elif re.fullmatch(r'rock(?:s|ed|ing)?', lower):
        value = -2.2 if lower == 'rock' else -1.3
    elif re.fullmatch(r'roll(?:s|ed|ing)?', lower):
        value = -0.5

    # Some R-initial spellings also fire when divided across tokens.
    if token[:1].isalpha():
        isolated_r = previous.strip(' ._-/').lower() == 'r'
        if tail_lower.endswith('r'):
            if lower in ('un', 'und', 'unning', 'unner'):
                value = -7.0
                if tail_lower.endswith('rer'):
                    value = -16.0 if lower == 'un' else -10.5
            elif lower in ('an', 'ung') and isolated_r:
                value = -2.1 if token == 'AN' else -7.0
            elif lower == 'ock':
                value = -6.5
            elif lower in ('ul', 'ace', 'acer') and isolated_r:
                value = -4.0
        if (lower in ('ck', 'cks')
                and re.search(r'r[aeiouyäöü]+$', tail_lower)):
            value = -2.7
        if tail_lower.endswith('run') and lower in ('s', 'ner', 'ners'):
            value = -3.3 if lower == 's' else -7.0
        # Long-vowel letter groups contrast with the negative short spellings.
        if (tail_lower.endswith('r')
                and lower in ('ane', 'one', 'ue', 'oo', 'oe')):
            value = 2.8
        elif tail_lower.endswith('ro') and lower in ('an', 'ans', 'ane', 'e'):
            value = 3.0 if lower == 'e' else 5.5
    if lower in ('roo', 'rue'):
        value = 2.0 if lower == 'roo' else 1.0
    return (doc, token, (tail + token)[-24:]), value

