"""Component layers.1.mlp.down_proj:1784: a "run" word detector.

The component goes negative on the word "run" and its forms. It is most negative on
"runner" (including "TestRunner" and "Runner"), and on the all-caps "RUN" that test
runners print. It is weaker on "running", "runs", and on words that end in "run" when
split across tokens (the "un" of "Rer|un"). Other tokens predict about zero; the
middle-dot filler token "··" gets a fixed -2.6, a rare data artifact.

The program tracks the current word through the row, so a word split across tokens is
read whole, and a camel-case compound like "TestRunner" counts by its ending.
"""
import re

READS = ()
FILLER = "··"


def step(carry, prefix, upstream):
    word, doc = ("", None) if carry is None else carry
    if prefix.document_ids[-1] != doc:
        word = ""
    s = prefix.token_strings[-1]
    if re.fullmatch(r"[A-Za-z]+", s):
        word = (word + s)[-30:]
    else:
        word = re.search(r"[A-Za-z]*$", s).group()
    w = word.lower()
    if s == FILLER:
        value = -2.6
    elif word == "RUN":
        value = -6.0
    elif w.endswith(("runner", "runners")):
        value = -6.0
    elif w.endswith(("running",)):
        value = -2.9
    elif w.endswith(("run", "runs")):
        value = -3.6
    elif w == "ran":
        value = -3.6
    elif w in ("race", "races", "racing", "rock", "rocks", "rush"):
        value = -1.5
    else:
        value = 0.0
    return (word, prefix.document_ids[-1]), value

