"""A sparse text/syntax detector in the second MLP.

The largest reproducible rules are the colon of a document-initial
``Title:`` field, runs of middle dots, and negative responses to Chinese
politics/modernity vocabulary.  Ring characters have a positive response.
A few rules approximate the different baseline at a document's first token.
Most other tokens get zero: this deliberately omits weak lexical variation
and the irregular responses to pieces of rare Unicode characters.
"""

READS = ()

# Closed-class words, not an arbitrary list of tokenizer IDs.
FUNCTION_WORDS = frozenset('''
a an the of to in on at by for from with and or but as if that this
these those it its is are was were be been being i you he she we they
my your his her our their me him us them all some any not no
'''.split())
CODE_OPENERS = frozenset('import from class def'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    state = (doc, position + 1, text)

    if position == 1 and previous == 'Title' and text == ':':
        return state, 7.0
    if len(text) >= 2 and set(text) == {'·'}:
        return state, -1.0

    if '政治' in text:
        value = -2.4 if text == '政治' else -1.7
    elif previous.endswith('政') and text.startswith('治'):
        value = -2.2
    elif text == '现代':
        value = -0.7
    elif text == '政策':
        value = -0.3
    elif text in {'环', '環'}:
        value = 0.75 if text == '环' else 0.45
    else:
        value = 0.0

    if position == 0:
        word = text.strip()
        if word == '\\':
            value = 1.42 if text == word else 0.91
        elif word == '\\t':
            value = -1.39
        elif word in {'"""', "'''"}:
            value = 1.36
        elif word.startswith(('//', '/*')):
            value = 0.6
        elif text in {'function', 'var'}:
            value = 1.3
        elif text in CODE_OPENERS:
            value = 0.6
        elif word.isascii() and word.isdigit():
            value = -0.4
        elif len(word) == 1 and word.isascii() and word.isalpha():
            value = -0.4
        elif text.startswith(' ') and word.lower() in FUNCTION_WORDS:
            value = -0.35
        elif text == '<|im_start|>':
            value = 0.36
    return state, float(value)

"""Detect short alphabetic pieces at line and quotation boundaries.

A capital letter token without a leading space is strongly negative after a
newline, moderately negative after a quote, and near zero inside words.
I, Q and X have weaker line-start responses; A is intermediate. Lowercase
fragments have a smaller boundary response. A space-prefixed capital in an
all-capitals token is negative too. Most other tokens are near zero, apart
from a positive offset for multi-character tokens at row/document starts or
immediately after a special marker. State resets between documents.
"""
import unicodedata

READS = ()
QUOTES = frozenset('\"\'“‘«`')


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, s)
    w = s.strip()
    first = w[:1]
    if not previous or previous.startswith('<|'):
        value = 0.0
        if len(w) > 1:
            value = 0.15 if first.islower() else 0.25
        return carry, value
    newline = '\n' in previous
    last = previous[-1:]
    quote = last in QUOTES
    if len(s) == 1 and s.isalpha():
        if s.isupper():
            if newline:
                latin = 'LATIN' in unicodedata.name(s, '')
                value = -1.55 if latin else -0.32
                if s == 'I':
                    value = -0.26
                elif s == 'A':
                    value = -1.10
                elif s == 'Q':
                    value = 0.02
                elif s == 'X':
                    value = -0.28
            elif quote:
                value = -0.73
            elif last in '([{<' and len(previous) == 1:
                value = 0.0
            elif not last.isalnum() and not last.isspace():
                value = -0.30
            else:
                value = 0.02 if last.isupper() else -0.045
                if last.islower() and len(previous.strip()) > 2:
                    value = -0.15
            return carry, value
        if s.islower() and quote:
            return carry, -0.27
        if s.islower() and newline:
            return carry, -0.87 if len(previous) == 1 else -0.35
    if (len(w) == 1 and w.isupper() and s[:1].isspace()
            and previous.strip().isupper() and len(previous.strip()) > 1):
        return carry, -0.60
    if first.islower() and newline:
        return carry, -0.07 if len(s) <= 3 else -0.015
    if first and 'CYRILLIC' in unicodedata.name(first, '') and w.isupper():
        return carry, 0.10
    return carry, 0.002

