"""Layer 1, MLP down_proj, component 1787: a "word-fragment capital at a line start" detector.

What it does, in plain terms:
- It goes strongly negative on a single capital letter that starts a new line (or a new
  quoted or parenthesised span), e.g. the "R" of "\\nRooftop" or the "S" of "\\nSazerac".
  Such a letter is usually the first piece of a longer word, so the model has to start a
  word whose rest it has not yet seen. It is most negative after a blank line.
- It is weakly negative on a single capital letter elsewhere, and on a lowercase single
  letter or "In" at the start of a line.
- It is mildly positive at the first token of a document (after <|endoftext|>, or at the
  start of a row), where attention has nothing before it.
- Everything else is near zero.
Only the current token and the one before it are read; no state is carried.
"""

READS = ()

OPENERS = {'"', "'", "“", "‘", "„", "«", "(", "["}
# Capital letters that are complete words or rarely begin a word fragment.
WHOLE_WORD_CAPS = {"I", "Q"}


def is_letter(s):
    return len(s) == 1 and s.isalpha()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.15  # first token of a document
    prev = prefix.token_strings[-2]
    if prev == "<|endoftext|>":
        return None, 0.15
    at_line_start = "\n" in prev
    if is_letter(cur) and cur.isupper() and cur not in WHOLE_WORD_CAPS:
        if at_line_start:
            return None, -1.4 if "\n\n" in prev else -1.15
        if prev.strip() in OPENERS:
            return None, -0.6
        return None, -0.05
    if at_line_start and is_letter(cur) and cur.islower():
        return None, -0.45
    if at_line_start and cur == "In":
        return None, -0.7
    return None, 0.0

programs.sol:
"""A syntax-sensitive response to conditionals and loops.

Prose 'if' is positive, except the weaker 'whether' sense after verbs such
as 'check'. Statement-initial 'if' is negative: strongly in semicolon-based
code, moderately in brace-only code, weakly otherwise. Loops and collection
type names have related negative responses. Python, Go, and Rust syntax
soften the code response; parenthesized Lisp-style `(if` stays small.
Other control-flow and test words have smaller negative responses.
Indentation, diff markers, and escaped code are recognized with a bounded
recent-text buffer; it resets at document boundaries.
"""
import re

READS = ()
QUESTION_VERBS = {
    'check', 'checking', 'checks', 'see', 'know', 'knows', 'determine',
    'wonder', 'wondering', 'sure', 'ask', 'asks', 'asked', 'decide',
    'tell', 'verify', 'test',
}
COLLECTIONS = {'List': 1., 'Collection': .9, 'Map': .65, 'Set': .4}
CONTROL = {'else': 2.2, 'catch': 2.5, 'try': 1.3, 'elseif': 4.8,
           'break': 1.3, 'continue': .8, 'expect': 2.5}
WORDS = ({'if', 'for', 'while', 'foreach', 'switch'}
         | COLLECTIONS.keys() | CONTROL.keys())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    past = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    state = (doc, (past + token)[-900:])
    word = token.strip().lstrip('(.<;')
    if word.lower() != 'if' and word not in WORDS:
        return state, 0.
    text = re.sub(r'\\+([nt])',
                  lambda m: '\n' if m[1] == 'n' else '\t', past)
    text = text.replace('\r', '\n')
    # A suffix of an identifier is not a standalone keyword or type name.
    if token[:1].isalnum() and (text[-1:].isalnum() or text.endswith('_')):
        return state, 0.
    line = text.rsplit('\n', 1)[-1]
    recent = text[-600:]
    semi = ';' in recent
    brace = '{' in text[-200:]
    statement = bool(past) and bool(re.fullmatch(r'[\s\d`+/*-]*', line))
    statement |= bool(re.search(r'(?:\u00a0[` ]*){2,}$|:\d+:\s*$', line))
    last = text.rstrip(' \n\t`')[-1:]
    after_else = bool(re.search(r'\belse\s*$', text))
    statement |= token.startswith(';') or line.lstrip().startswith('#define')
    c_declaration = bool(re.search(
        r'\b(public|private|protected)\b|#include'
        r'|\bfunction\s+\w*\s*\(|\bconst\s+\w+\s*=', recent))
    statement |= (bool(line.strip()) and (semi or c_declaration)
                  and (last == '{' or (token == 'if' and last == ';')))
    go = ':=' in recent or bool(re.search(r'\bfunc\s+\w|\bpackage\s+\w', recent))
    rust = bool(re.search(r'\b(fn|impl|mut|crate)\b', recent))
    python = bool(re.search(
        r'\bdef\s+\w+\s*\(|\bself\.|\belif\b'
        r'|\b(print|range)\s*\(', recent))
    value = 0.
    if word.lower() == 'if':
        words = re.findall(r'[a-z]+', text[-70:].lower())
        previous = words[-1] if words else ''
        value = .94
        if previous in QUESTION_VERBS or previous == 'as':
            value = .15
        elif previous in {'even', 'only'}:
            value = .52
        if word == 'if':
            if token.lstrip().startswith('(if'):
                value = .3
            elif after_else:
                value = -4.6
            elif statement:
                if rust or go:
                    value = -3.7
                elif python:
                    value = -.9
                elif c_declaration:
                    value = -8.6
                elif semi:
                    value = -7.3
                else:
                    value = -6.3 if last == '{' else -4.2 if brace else -1.1
            elif text[-60:].count(';') >= 2:
                value = -3.8
    elif word in {'for', 'while', 'foreach', 'switch'}:
        value = .08 if word == 'for' else .2
        loop_boundary = statement or (last in (';', '{') and len(line) < 34)
        # A TeX text box is prose, not a programming-language block.
        if re.search(r'\\(hbox|textrm|text|mathrm)\{$', past):
            loop_boundary = False
        if loop_boundary:
            if word == 'for':
                if rust or python:
                    value = -.3
                elif go:
                    value = -2.0
                elif last in (';', '{'):
                    value = -5.8
                elif semi:
                    value = -4.8
                else:
                    value = -.25
            else:
                value = -5.8 if semi else -3.0 if brace else -1.0
    elif word in CONTROL and (statement or after_else):
        value = -CONTROL[word] if (semi or brace) and not python else -.2
    elif word in COLLECTIONS:
        type_context = (c_declaration or ';' in text[-60:]
                        or bool(re.search(r'\bnew\s*$|java\.util\.?$', text)))
        if type_context:
            declaration = re.search(r'\b(public|private|protected)\s*$', text)
            value = -(5.0 if declaration else 3.1) * COLLECTIONS[word]
    return state, value

"""A heuristic signal at the beginning of quoted code and literal values.

Shell code/pattern arguments, JSON tool fields and markup attributes are
positive. Character tests and string-search arguments are negative. A few
first content tokens retain a smaller response. Code fences, here-documents
and script tags have positive opening-boundary responses. Everything else
is nearly zero. Only recent text in the current document is retained.
"""
import re

READS = ()
QUOTE = re.compile(r'''([ \t([{=:+,\\`]*)(['"])([$\\#%<({./\-\n]*)''')
CODE_WORDS = {'import', 'from', 'const', 'var', 'let', 'require', 'def'}


def quoted(s, before):
    m = QUOTE.fullmatch(s)
    if not m:
        return None
    lead, mark, tail = m.groups()
    c = (before + lead).rstrip(' \\')
    if re.search(r'\bsed(?:\s+-[\w-]+)*$', c):
        return 8.2, 'sed'
    if re.search(r'(?:^|[\n;{}:])\s*case$', c):
        return -3.6, 'character'
    if not c.endswith(('<<', '=>')) and re.search(r'(==|!=|<=|>=|<|>)$', c):
        character = mark == "'" and re.search(r"'[^'\n]{1,2}'|\bchar\b", before)
        return (-3.0 if character else -0.9), 'character'
    if re.search(r'(?:find|index|startswith|endswith|compare|split|strip|'
                 r'replace|includes|contains|equals|match|search)\($', c, re.I):
        return (-1.8 if tail else -1.0), 'character'
    if re.search(r'\b(?:python[\d.]*|node|php|ruby|perl|bash|sh)\s+-[cer]$', c):
        return 5.8, 'code'
    escaped = '\\' in lead
    if re.search(r'\bgrep(?:\s+-[\w-]+)*$', c):
        return (3.6 if escaped else 1.5), 'pattern'
    if re.search(r'\becho$', c):
        return 1.5, None
    if re.search(r'\s--?[A-Za-z][\w-]*$', c):
        return 3.2, 'pattern'
    attribute = re.search(r'<[A-Za-z][^<>]*\s([:\w-]+)=$', c)
    if attribute:
        if attribute[1].startswith(('v-', ':')) or ':' in attribute[1]:
            return 6.0, None
        return (2.0 if escaped else 0.9), None
    if re.search(r'"name"\s*:\s*"[^"\n]+"\s*,$', c):
        return 2.05, 'tool_key'
    if re.search(r'"command"\s*:$', c):
        return 1.02, 'command'
    if '{' in lead:
        return 0.71, None
    if c.endswith('<<'):
        return (1.4 if mark == "'" else -0.2), None
    if c.endswith('('):
        return (-0.4 if tail else -0.07), None
    if '=' in lead:
        return (2.0 if escaped else 0.27), None
    if tail.startswith('$') and mark == '"':
        return 1.45, None
    if c.endswith(':'):
        return 0.38, None
    if c.endswith(','):
        return 0.23, None
    return (-0.3 if tail else 0.0), None


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', None)
    _, before, previous = carry
    result = quoted(s, before)
    value, event = result if result is not None else (-0.003, None)
    if result is None:
        if re.search(r"<<\s*'?$", before) and s.isupper() and s.isidentifier():
            value = 5.5
        elif s.isspace() and '\n' in s:
            if re.search(r'(?:^|\n)\s*```[\w+-]+$', before):
                value = 1.5
        elif re.search(r'<script\b[^>]*$', before) and s.startswith('>'):
            value = 3.3
        elif previous == 'character' and len(s) == 1 and s.isalnum():
            value = -2.0
        elif previous and s.isalnum():
            if previous == 'tool_key':
                value = 1.44
            elif previous == 'command':
                value = 0.23
            elif previous == 'sed':
                value = 6.2 if s == 's' else 2.6
            elif previous == 'code':
                value = 2.8 if s in CODE_WORDS else 0.5
            elif previous == 'pattern':
                value = 0.6
    return (doc, (before + s)[-240:], event), float(value)

programs.haiku:
"""Opening quotation marks: the quote that starts a string literal. Its activation depends on
what the string is for, judged from the word just before the quote:
  - a shell command or heredoc argument (echo "..", grep '..', sed -i '..', python -c "..",
    curl -H '..', <<'EOF'): positive;
  - a JSON key or value after a comma or colon (tool-call arguments, dict entries): positive;
  - an HTML event handler (onclick="..."): strongly positive;
  - a comparison, return value, or switch-case label in code (== '..', case '..', return '..'):
    negative;
  - anything else, including closing quotes: about zero."""

READS = ()

SHELL_CUES = {"echo", "grep", "awk", "wget", "eval", "curl", "sed", "-i", "-H", "c", "-c"}
CODE_CUES = {"==", "===", "!=", "!==", "if", "elif", "case", "return", ".replace", ".put"}
HTML_CUES = {"onclick": 8.0, "href": 1.5, "style": 1.5, "target": 1.5}
OPEN_CHARS = set(' \t=({[:,\\"\'')

def is_opening_quote(s):
    """A token that is only spacing or punctuation followed by a quote mark, e.g. ' "', '="'."""
    return s.endswith(('"', "'")) and all(ch in OPEN_CHARS for ch in s)

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2].strip() if len(toks) > 1 else ""
    near = "".join(toks[-9:-1])     # the 8 tokens before this one
    wide = "".join(toks[-31:-1])    # the 30 tokens before this one
    if cur == "arguments" and prev.endswith('"'):
        return carry, 1.5           # the key after a tool call's tool name
    if "EOF" in cur and "<<" in near:
        return carry, 6.0           # heredoc marker
    if cur in ('"', "'", '\\"') or not is_opening_quote(cur):
        return carry, 0.0
    if prev in HTML_CUES:
        return carry, HTML_CUES[prev]
    if prev in SHELL_CUES:
        return carry, 2.8
    if prev in CODE_CUES:
        return carry, -1.5
    if "sed -" in near:
        return carry, 5.0
    if prev in ('",', '":'):
        return carry, 0.9
    if '"name"' in wide or "tool_call" in wide:
        return carry, 1.0
    return carry, 0.1

programs.sol:
"""A sparse lexical approximation, dominated by East Asian calendar units.

A number followed by a month marker gets the largest ordinary response;
day/year markers and month-period suffixes get smaller responses. Other
rules distinguish speed, random-number calls, creation notices, 'health
care', 'at rest', empty braces and the degree marker. Initial blank comments,
carriage returns and nonbreaking spaces have separate formatting responses.
Everything else gets a near-zero baseline. Recent bytes preserve split UTF-8
characters, and all state resets at document boundaries. This captures only
part of the component, not its diffuse background variation.
"""
import re

READS = ()
CHINESE_NUMERALS = set('一二三四五六七八九十两〇零')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, blank = b'', True
    else:
        _, recent, blank = carry
    history = recent.decode('utf-8', 'replace')
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    number = re.search(r'(\d+)$', history)
    chinese_number = bool(history and history[-1] in CHINESE_NUMERALS)
    value = -0.003

    if token in ('月', '월'):
        if number:
            value = 3.68 if len(number[0]) == 1 else 3.91
            if token == '월':
                value -= 0.7
        else:
            value = 2.1 if chinese_number else 0.08
    elif token in ('日', '일') and (number or chinese_number):
        value = 0.86 if number else 0.6
    elif token in ('年', '년') and number:
        value = 0.34 if len(number[0]) == 4 else 0.1
        if token == '년' and len(number[0]) == 4:
            value = 0.23
    elif token in ('月份', '月底', '月初', '月中旬', '月以来'):
        if number or chinese_number:
            value = 0.8 if token in ('月初', '月中旬') else 1.4
    elif word in ('speed', 'speeds'):
        value = 0.45 if token.strip()[0].isupper() else 0.6
        if re.search(r'\b(initial|constant)\s*$', history, re.I):
            value = 1.7
    elif token == '速':
        value = 0.7
    elif word == 'random' or token == '.random':
        if token.startswith('.'):
            value = 1.55 if history.endswith('np') else 0.5
            if history.endswith('Math'):
                value = 1.25
        else:
            value = 0.0 if token.strip()[0].isupper() else 0.13
            if re.search(r'\bat\s*$', history, re.I):
                value = 1.25
    elif word == 'created':
        value = 0.1
        if re.search(r'\b(file|socket)\s*$', history, re.I):
            value = 1.4
        elif not token.startswith(' '):
            value = 0.9
        elif token.strip()[0].isupper():
            value = 0.47
    elif word == 'care':
        value = -0.06
        if re.search(r'\bhealth\s*$', history, re.I):
            value = -0.75 if token.startswith(' ') else -0.3
    elif word == 'rest':
        value = 0.65 if re.search(r'\bat\s*$', history, re.I) else -0.12
    elif token.lstrip(' ') == '{}':
        value = -0.43
    elif token == '度':
        value = -1.0 if number or chinese_number else -0.23
    elif blank and token == '//\n':
        value = 7.65
    elif blank and token == '\r':
        value = 4.48
    elif blank and token == '\xa0':
        value = 1.33

    recent = (recent + prefix.token_bytes[-1])[-300:]
    return (doc, recent, blank and token.isspace()), value
